insert into public.rules (course_name, lesson_number, title, content, sort_order, rule_kind, summary) values
('Мединский курс (Том 1)', '1', 'اِسْمُ الْإِشَارَةِ لِلْمُفْرَدِ الْمُذَكَّرِ الْقَرِيبِ: هَذَا (указательное слово «это/этот»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">اِسْمُ الْإِشَارَةِ لِلْمُفْرَدِ الْمُذَكَّرِ الْقَرِيبِ: هَذَا</span><p class="rule-study-text">указательное слово «это/этот». Суть правила. هَذَا употребляется с одним предметом или лицом мужского рода, находящимся близко: هَذَا كِتَابٌ — «Это книга». Отдельного слова «есть» в настоящем времени не требуется. Дополнительное объяснение.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">جُمْلَةٌ اِسْمِيَّةٌ</span><span class="rule-term-ru">именное предложение</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُبْتَدَأُ</span><span class="rule-term-ru">подлежащее именного предложения; первый главный член الجُمْلَةُ الِاسْمِيَّةُ</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar" dir="rtl" lang="ar">الْخَبَرُ</span><span class="rule-term-ru">сказуемое / сообщение о الْمُبْتَدَأُ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا كِتَابٌ</span><span class="rule-term-ru">«Это книга»</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">указательное слово в позиции первого члена предложения, а следующее неопределённое существ</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمٌ</span><span class="rule-term-ru">имя: существительное, прилагательное, местоимение или другое именное слово</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">مُبْتَدَأٌ</span><span class="rule-term-ru">подлежащее именного предложения</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar" dir="rtl" lang="ar">خَبَرٌ</span><span class="rule-term-ru">сказуемое / сообщение о مُبْتَدَأٌ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا بَيْتٌ.</span><span class="rule-example-ru">Это дом. هَذَا указывает на близкий предмет; بَيْتٌ сообщает, что это за предмет.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا مُدَرِّسٌ.</span><span class="rule-example-ru">Это учитель. Слово مُدَرِّسٌ неопределённое и получает танвин.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>Суть правила.</b> <b>هَذَا</b> употребляется с одним предметом или лицом мужского рода, находящимся близко: <b>هَذَا كِتَابٌ</b> — «Это книга». Отдельного слова «есть» в настоящем времени не требуется.<br><br><b>Дополнительное объяснение.</b> Это именное предложение <b>جُمْلَةٌ اِسْمِيَّةٌ</b>. <b>هَذَا</b> — указательное слово в позиции первого члена предложения, а следующее неопределённое существительное сообщает, что это за предмет. Алиф после <b>هَاء</b> произносится, но в стандартном написании слова не обозначается отдельной буквой: <b>هَذَا</b>, а не <b>هَاذَا</b>. Термины <b>الْمُبْتَدَأُ</b> и <b>الْخَبَرُ</b> вводятся позже, в уроках 13 и 17.<br><br><ul><li><b>هَذَا بَيْتٌ.</b> — Это дом. <b>هَذَا</b> указывает на близкий предмет; <b>بَيْتٌ</b> сообщает, что это за предмет.</li><li><b>هَذَا مُدَرِّسٌ.</b> — Это учитель. Слово <b>مُدَرِّسٌ</b> неопределённое и получает танвин.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 1, 'rule', 'Название и смысл اِسْمُ الْإِشَارَةِ لِلْمُفْرَدِ الْمُذَكَّرِ الْقَرِيبِ: هَذَا указательное слово «это/этот». Суть правила. هَذَا употребляется с одним предметом или лицом мужского рода, находящимся близко: هَذَا كِتَابٌ — «Это книга». От'),
('Мединский курс (Том 1)', '1', 'مَا؟ وَمَنْ؟ (вопросы «что?» и «кто?»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مَا؟ وَمَنْ؟</span><p class="rule-study-text">вопросы «что?» и «кто?». مَا هَذَا؟ спрашивает о предмете: «Что это?» مَنْ هَذَا؟ спрашивает о человеке: «Кто это?» مَا هَذَا؟ هَذَا قَلَمٌ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَا؟ وَمَنْ؟</span><span class="rule-term-ru">вопросы «что?» и «кто?»</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">это / этот: указательное имя для близкого мужского рода</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَا هَذَا؟ هَذَا قَلَمٌ.</span><span class="rule-example-ru">Что это? Это ручка.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَنْ هَذَا؟ هَذَا طَالِبٌ.</span><span class="rule-example-ru">Кто это? Это студент.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>مَا هَذَا؟</b> спрашивает о предмете: «Что это?» <b>مَنْ هَذَا؟</b> спрашивает о человеке: «Кто это?»<br><br><ul><li><b>مَا هَذَا؟ هَذَا قَلَمٌ.</b> — Что это? Это ручка.</li><li><b>مَنْ هَذَا؟ هَذَا طَالِبٌ.</b> — Кто это? Это студент.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 2, 'rule', 'Название и смысл مَا؟ وَمَنْ؟ вопросы «что?» и «кто?». مَا هَذَا؟ спрашивает о предмете: «Что это?» مَنْ هَذَا؟ спрашивает о человеке: «Кто это?» مَا هَذَا؟ هَذَا قَلَمٌ. Арабские слова → русский смысл مَا؟ وَمَنْ؟ вопросы «что?» и «кто?» ه'),
('Мединский курс (Том 1)', '1', 'هَمْزَةُ الِاسْتِفْهَامِ، نَعَمْ، لَا (вопросительная أَ, «да», «нет»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">هَمْزَةُ الِاسْتِفْهَامِ، نَعَمْ، لَا</span><p class="rule-study-text">вопросительная أَ, «да», «нет». Частица أَ ставится перед утверждением и превращает его в общий вопрос. Ответ: نَعَمْ — да; لَا — нет. أَهَذَا بَيْتٌ؟ نَعَمْ، هَذَا بَيْتٌ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">هَمْزَةُ الِاسْتِفْهَامِ، نَعَمْ، لَا</span><span class="rule-term-ru">вопросительная أَ, «да», «нет»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">نَعَمْ</span><span class="rule-term-ru">да</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">это / этот: указательное имя для близкого мужского рода</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">أَهَذَا بَيْتٌ؟ نَعَمْ، هَذَا بَيْتٌ.</span><span class="rule-example-ru">Это дом? Да, это дом.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">أَهَذَا كَلْبٌ؟ لَا، هَذَا قِطٌّ.</span><span class="rule-example-ru">Это собака? Нет, это кот.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">Частица <b>أَ</b> ставится перед утверждением и превращает его в общий вопрос. Ответ: <b>نَعَمْ</b> — да; <b>لَا</b> — нет.<br><br><ul><li><b>أَهَذَا بَيْتٌ؟ نَعَمْ، هَذَا بَيْتٌ.</b> — Это дом? Да, это дом.</li><li><b>أَهَذَا كَلْبٌ؟ لَا، هَذَا قِطٌّ.</b> — Это собака? Нет, это кот.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 3, 'rule', 'Название и смысл هَمْزَةُ الِاسْتِفْهَامِ، نَعَمْ، لَا вопросительная أَ, «да», «нет». Частица أَ ставится перед утверждением и превращает его в общий вопрос. Ответ: نَعَمْ — да; لَا — нет. أَهَذَا بَيْتٌ؟ نَعَمْ، هَذَا بَيْتٌ. Арабские сло'),
('Мединский курс (Том 1)', '1', 'التَّنْوِينُ وَالتَّنْكِيرُ (танвин и неопределённость)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">التَّنْوِينُ وَالتَّنْكِيرُ</span><p class="rule-study-text">танвин и неопределённость. Окончание ـٌ в формах كِتَابٌ، بَيْتٌ، مَسْجِدٌ показывает неопределённость и именительный падеж. Оно не переводится отдельным словом. Дополнительное объяснение: это تَنْوِينُ الضَّمِّ , а существительное здесь обычно является именительной частью сообщения.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">التَّنْوِينُ وَالتَّنْكِيرُ</span><span class="rule-term-ru">танвин и неопределённость</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок отдельно.</li><li>Сравните русский смысл с примером.</li><li>Проверьте роль слов и их окончание.</li></ol></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">Окончание <b>ـٌ</b> в формах <b>كِتَابٌ، بَيْتٌ، مَسْجِدٌ</b> показывает неопределённость и именительный падеж. Оно не переводится отдельным словом. <b>Дополнительное объяснение:</b> это <b>تَنْوِينُ الضَّمِّ</b>, а существительное здесь обычно является именительной частью сообщения.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не переводите правило отдельно от арабского примера: форма слова видна именно в предложении.</div></div>', 4, 'rule', 'Название и смысл التَّنْوِينُ وَالتَّنْكِيرُ танвин и неопределённость. Окончание ـٌ в формах كِتَابٌ، بَيْتٌ، مَسْجِدٌ показывает неопределённость и именительный падеж. Оно не переводится отдельным словом. Дополнительное объяснение: это تَ'),
('Мединский курс (Том 1)', '1', 'الْمَعْرِفَةُ وَالنَّكِرَةُ (определённое и неопределённое имя)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمَعْرِفَةُ وَالنَّكِرَةُ</span><p class="rule-study-text">определённое и неопределённое имя. الْمَعْرِفَةُ — определённое, известное имя. النَّكِرَةُ — неопределённое имя. Это правило помогает понять, почему в начале курса одно слово получает танвин, а другое — артикль أَلْـ . كِتَابٌ — книга / какая-то книга.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْمَعْرِفَةُ وَالنَّكِرَةُ</span><span class="rule-term-ru">определённое и неопределённое имя</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْمَعْرِفَةُ</span><span class="rule-term-ru">определённое, известное имя</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">النَّكِرَةُ</span><span class="rule-term-ru">неопределённое имя</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">كِتَابٌ</span><span class="rule-term-ru">книга / какая-то книга</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الْكِتَابُ</span><span class="rule-term-ru">эта известная книга / книга с артиклем</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا كِتَابٌ</span><span class="rule-term-ru">Это книга</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا الْكِتَابُ</span><span class="rule-term-ru">Эта книга</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">это / этот: указательное имя для близкого мужского рода</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَلْـ</span><span class="rule-term-ru">определённый артикль</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">كِتَابٌ</span><span class="rule-example-ru">книга / какая-то книга.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">الْكِتَابُ</span><span class="rule-example-ru">эта известная книга / книга с артиклем.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا كِتَابٌ</span><span class="rule-example-ru">Это книга.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا الْكِتَابُ</span><span class="rule-example-ru">Эта книга.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><p><b>الْمَعْرِفَةُ</b> — определённое, известное имя. <b>النَّكِرَةُ</b> — неопределённое имя. Это правило помогает понять, почему в начале курса одно слово получает танвин, а другое — артикль <b>أَلْـ</b>.</p><ul><li>كِتَابٌ — книга / какая-то книга.</li><li>الْكِتَابُ — эта известная книга / книга с артиклем.</li><li>هَذَا كِتَابٌ — Это книга.</li><li>هَذَا الْكِتَابُ — Эта книга.</li></ul><p>К определённым словам относятся, например: имена собственные, местоимения, указательные слова, слова с <b>أَلْـ</b> и слово в идафе, если оно определяется вторым членом.</p></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 5, 'rule', 'Название и смысл الْمَعْرِفَةُ وَالنَّكِرَةُ определённое и неопределённое имя. الْمَعْرِفَةُ — определённое, известное имя. النَّكِرَةُ — неопределённое имя. Это правило помогает понять, почему в начале курса одно слово получает танвин, а '),
('Мединский курс (Том 1)', '2', 'اِسْمُ الْإِشَارَةِ لِلْمُفْرَدِ الْمُذَكَّرِ الْبَعِيدِ: ذَلِكَ (указательное слово «тот»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">اِسْمُ الْإِشَارَةِ لِلْمُفْرَدِ الْمُذَكَّرِ الْبَعِيدِ: ذَلِكَ</span><p class="rule-study-text">указательное слово «тот». ذَلِكَ относится к одному удалённому предмету или лицу мужского рода. ذَلِكَ مَسْجِدٌ. — То — мечеть. مَا ذَلِكَ؟</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ذَلِكَ</span><span class="rule-term-ru">то / тот: указательное имя для далёкого мужского рода</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمٌ</span><span class="rule-term-ru">имя: существительное, прилагательное, местоимение или другое именное слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">ذَلِكَ مَسْجِدٌ.</span><span class="rule-example-ru">То — мечеть.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">مَا ذَلِكَ؟ ذَلِكَ حَجَرٌ.</span><span class="rule-example-ru">Что это? Это камень.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>ذَلِكَ</b> относится к одному удалённому предмету или лицу мужского рода.<br><br><ul><li><b>ذَلِكَ مَسْجِدٌ.</b> — То — мечеть.</li><li><b>مَا ذَلِكَ؟ ذَلِكَ حَجَرٌ.</b> — Что это? Это камень.</li></ul><br><br><b>Примечание.</b> В <b>ذَلِكَ</b> алиф после <b>ذَ</b> произносится, но отдельной буквой не пишется.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 1, 'rule', 'Название и смысл اِسْمُ الْإِشَارَةِ لِلْمُفْرَدِ الْمُذَكَّرِ الْبَعِيدِ: ذَلِكَ указательное слово «тот». ذَلِكَ относится к одному удалённому предмету или лицу мужского рода. ذَلِكَ مَسْجِدٌ. — То — мечеть. مَا ذَلِكَ؟ Арабские слова → р'),
('Мединский курс (Том 1)', '2', 'حَرْفُ الْعَطْفِ: وَ (союз «и»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">حَرْفُ الْعَطْفِ: وَ</span><p class="rule-study-text">союз «и». وَ присоединяется к следующему слову без пробела в арабской записи. هَذَا بَيْتٌ وَذَلِكَ مَسْجِدٌ. — Это дом, а то мечеть. هَذَا سُكَّرٌ وَذَلِكَ لَبَنٌ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">حَرْفُ الْعَطْفِ: وَ</span><span class="rule-term-ru">союз «и»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">حَرْفُ عَطْفٍ</span><span class="rule-term-ru">союзная частица, соединяющая слова или предложения</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">союз حَرْفُ عَطْفٍ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">это / этот: указательное имя для близкого мужского рода</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ذَلِكَ</span><span class="rule-term-ru">то / тот: указательное имя для далёкого мужского рода</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">حَرْفٌ</span><span class="rule-term-ru">частица / служебное слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا بَيْتٌ وَذَلِكَ مَسْجِدٌ.</span><span class="rule-example-ru">Это дом, а то мечеть.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا سُكَّرٌ وَذَلِكَ لَبَنٌ.</span><span class="rule-example-ru">Это сахар, а то молоко.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>وَ</b> присоединяется к следующему слову без пробела в арабской записи.<br><br><ul><li><b>هَذَا بَيْتٌ وَذَلِكَ مَسْجِدٌ.</b> — Это дом, а то мечеть.</li><li><b>هَذَا سُكَّرٌ وَذَلِكَ لَبَنٌ.</b> — Это сахар, а то молоко.</li></ul><br><br><b>Дополнительное объяснение:</b> <b>وَ</b> — союз <b>حَرْفُ عَطْفٍ</b>; в русском переводе по смыслу возможны «и» или «а».</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 2, 'rule', 'Название и смысл حَرْفُ الْعَطْفِ: وَ союз «и». وَ присоединяется к следующему слову без пробела в арабской записи. هَذَا بَيْتٌ وَذَلِكَ مَسْجِدٌ. — Это дом, а то мечеть. هَذَا سُكَّرٌ وَذَلِكَ لَبَنٌ. Арабские слова → русский смысл حَرْفُ'),
('Мединский курс (Том 1)', '3', 'أَدَاةُ التَّعْرِيفِ: أَلْـ (определённый артикль)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَدَاةُ التَّعْرِيفِ: أَلْـ</span><p class="rule-study-text">определённый артикль. Артикль أَلْـ делает существительное определённым: بَيْتٌ — «какой-то дом», الْبَيْتُ — «этот/известный дом». При присоединении артикля танвин исчезает. هَذَا بَيْتٌ. الْبَيْتُ جَدِيدٌ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَدَاةُ التَّعْرِيفِ: أَلْـ</span><span class="rule-term-ru">определённый артикль</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">بَيْتٌ</span><span class="rule-term-ru">«какой-то дом», الْبَيْتُ — «этот/известный дом»</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">это / этот: указательное имя для близкого мужского рода</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَلْـ</span><span class="rule-term-ru">определённый артикль</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا بَيْتٌ. الْبَيْتُ جَدِيدٌ.</span><span class="rule-example-ru">Это дом. Дом новый.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">الْبَابُ مَفْتُوحٌ.</span><span class="rule-example-ru">Дверь открыта.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">Артикль <b>أَلْـ</b> делает существительное определённым: <b>بَيْتٌ</b> — «какой-то дом», <b>الْبَيْتُ</b> — «этот/известный дом». При присоединении артикля танвин исчезает.<br><br><ul><li><b>هَذَا بَيْتٌ. الْبَيْتُ جَدِيدٌ.</b> — Это дом. Дом новый.</li><li><b>الْبَابُ مَفْتُوحٌ.</b> — Дверь открыта.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 1, 'rule', 'Название и смысл أَدَاةُ التَّعْرِيفِ: أَلْـ определённый артикль. Артикль أَلْـ делает существительное определённым: بَيْتٌ — «какой-то дом», الْبَيْتُ — «этот/известный дом». При присоединении артикля танвин исчезает. هَذَا بَيْتٌ. الْبَي'),
('Мединский курс (Том 1)', '3', 'الْحُرُوفُ الْقَمَرِيَّةُ وَالشَّمْسِيَّةُ (лунные и солнечные буквы)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْحُرُوفُ الْقَمَرِيَّةُ وَالشَّمْسِيَّةُ</span><p class="rule-study-text">лунные и солнечные буквы. Перед лунной буквой لْ артикля произносится: الْقَمَرُ، الْبَيْتُ . Перед солнечной буквой звук لْ не произносится, а следующая буква удваивается: الشَّمْسُ، الرَّجُلُ، الطَّالِبُ . Солнечные буквы: ت، ث، د، ذ، ر، ز، س، ش، ص، ض، ط، ظ، ل، ن . Остальные — лунные.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْحُرُوفُ الْقَمَرِيَّةُ وَالشَّمْسِيَّةُ</span><span class="rule-term-ru">лунные и солнечные буквы</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок отдельно.</li><li>Сравните русский смысл с примером.</li><li>Проверьте роль слов и их окончание.</li></ol></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">Перед лунной буквой <b>لْ</b> артикля произносится: <b>الْقَمَرُ، الْبَيْتُ</b>. Перед солнечной буквой звук <b>لْ</b> не произносится, а следующая буква удваивается: <b>الشَّمْسُ، الرَّجُلُ، الطَّالِبُ</b>.<br><br>Солнечные буквы: <b>ت، ث، د، ذ، ر، ز، س، ش، ص، ض، ط، ظ، ل، ن</b>. Остальные — лунные.<br><br><b>Дополнительное объяснение.</b> Написание <b>ل</b> сохраняется в обоих случаях; меняется произношение. Удвоение солнечной буквы обозначается <b>شَدَّةٌ</b>.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не переводите правило отдельно от арабского примера: форма слова видна именно в предложении.</div></div>', 2, 'rule', 'Название и смысл الْحُرُوفُ الْقَمَرِيَّةُ وَالشَّمْسِيَّةُ лунные и солнечные буквы. Перед лунной буквой لْ артикля произносится: الْقَمَرُ، الْبَيْتُ . Перед солнечной буквой звук لْ не произносится, а следующая буква удваивается: الشَّمْ'),
('Мединский курс (Том 1)', '3', 'هَمْزَةُ الْوَصْلِ فِي أَلْـ (соединительная хамза артикля)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">هَمْزَةُ الْوَصْلِ فِي أَلْـ</span><p class="rule-study-text">соединительная хамза артикля. В начале речи артикль произносится с гласным: اَلْبَيْتُ . После предыдущего слова начальный гласный опускается: بَابُ الْبَيْتِ . Это явление называется هَمْزَةُ الْوَصْلِ .</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">هَمْزَةُ الْوَصْلِ فِي أَلْـ</span><span class="rule-term-ru">соединительная хамза артикля</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَلْـ</span><span class="rule-term-ru">определённый артикль</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">В начале речи артикль произносится с гласным: <b>اَلْبَيْتُ</b>. После предыдущего слова начальный гласный опускается: <b>بَابُ الْبَيْتِ</b>. Это явление называется <b>هَمْزَةُ الْوَصْلِ</b>.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 3, 'rule', 'Название и смысл هَمْزَةُ الْوَصْلِ فِي أَلْـ соединительная хамза артикля. В начале речи артикль произносится с гласным: اَلْبَيْتُ . После предыдущего слова начальный гласный опускается: بَابُ الْبَيْتِ . Это явление называется هَمْزَةُ ا'),
('Мединский курс (Том 1)', '4', 'حُرُوفُ الْجَرِّ (предлоги и родительный падеж)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">حُرُوفُ الْجَرِّ</span><p class="rule-study-text">предлоги и родительный падеж. В уроке вводятся فِي — в, عَلَى — на, а во второй части مِنْ — из/от и إِلَى — к/в. Существительное после предлога ставится в родительный падеж مَجْرُورٌ и обычно получает ـِ или ـٍ . الْكِتَابُ عَلَى الْمَكْتَبِ. — Книга на столе.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">حُرُوفُ الْجَرِّ</span><span class="rule-term-ru">предлоги и родительный падеж</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">مَجْرُورٌ</span><span class="rule-term-ru">в родительном падеже / в состоянии جرّ</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">فِي</span><span class="rule-term-ru">в, عَلَى — на, а во второй части مِنْ — из/от и إِلَى — к/в</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">الْكِتَابُ عَلَى الْمَكْتَبِ.</span><span class="rule-example-ru">Книга на столе.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">بِلَالٌ فِي الْمَسْجِدِ.</span><span class="rule-example-ru">Биляль в мечети.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">أَنَا مِنَ الْيَابَانِ.</span><span class="rule-example-ru">Я из Японии.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">ذَهَبَ الطَّالِبُ إِلَى الْجَامِعَةِ.</span><span class="rule-example-ru">Студент пошёл в университет.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">В уроке вводятся <b>فِي</b> — в, <b>عَلَى</b> — на, а во второй части <b>مِنْ</b> — из/от и <b>إِلَى</b> — к/в. Существительное после предлога ставится в родительный падеж <b>مَجْرُورٌ</b> и обычно получает <b>ـِ</b> или <b>ـٍ</b>.<br><br><ul><li><b>الْكِتَابُ عَلَى الْمَكْتَبِ.</b> — Книга на столе.</li><li><b>بِلَالٌ فِي الْمَسْجِدِ.</b> — Биляль в мечети.</li><li><b>أَنَا مِنَ الْيَابَانِ.</b> — Я из Японии.</li><li><b>ذَهَبَ الطَّالِبُ إِلَى الْجَامِعَةِ.</b> — Студент пошёл в университет.</li></ul><br><br><b>Дополнительное объяснение:</b> предложное сочетание может быть частью сообщения о предмете: <b>الْكِتَابُ عَلَى الْمَكْتَبِ</b>. Конечная <b>ـُ</b> у существительного сменяется на <b>ـِ</b> после предлога.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 1, 'rule', 'Название и смысл حُرُوفُ الْجَرِّ предлоги и родительный падеж. В уроке вводятся فِي — в, عَلَى — на, а во второй части مِنْ — из/от и إِلَى — к/в. Существительное после предлога ставится в родительный падеж مَجْرُورٌ и обычно получает ـِ и'),
('Мединский курс (Том 1)', '4', 'أَيْنَ؟ (вопрос «где?»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَيْنَ؟</span><p class="rule-study-text">вопрос «где?». أَيْنَ الْكِتَابُ؟ هُوَ عَلَى الْمَكْتَبِ. — Где книга? Она на столе.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَيْنَ؟</span><span class="rule-term-ru">вопрос «где?»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَيْنَ</span><span class="rule-term-ru">где?: вопросительное имя места</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">أَيْنَ الْكِتَابُ؟ هُوَ عَلَى الْمَكْتَبِ.</span><span class="rule-example-ru">Где книга? Она на столе.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">أَيْنَ آمِنَةُ؟ هِيَ فِي الْبَيْتِ.</span><span class="rule-example-ru">Где Амина? Она дома.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>أَيْنَ الْكِتَابُ؟ هُوَ عَلَى الْمَكْتَبِ.</b> — Где книга? Она на столе.</li><li><b>أَيْنَ آمِنَةُ؟ هِيَ فِي الْبَيْتِ.</b> — Где Амина? Она дома.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 2, 'rule', 'Название и смысл أَيْنَ؟ вопрос «где?». أَيْنَ الْكِتَابُ؟ هُوَ عَلَى الْمَكْتَبِ. — Где книга? Она на столе. Арабские слова → русский смысл أَيْنَ؟ вопрос «где?» مَنْ кто?: вопросительное имя для разумного أَيْنَ где?: вопросительное имя м'),
('Мединский курс (Том 1)', '4', 'ضَمِيرَا الْغَائِبِ: هُوَ وَهِيَ (местоимения «он/оно» и «она»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">ضَمِيرَا الْغَائِبِ: هُوَ وَهِيَ</span><p class="rule-study-text">местоимения «он/оно» и «она». هُوَ заменяет существительное мужского рода, هِيَ — женского. В арабском грамматический род не всегда совпадает с русским: كِتَابٌ — мужского рода, سَيَّارَةٌ — женского. أَيْنَ الْقَلَمُ؟ هُوَ فِي الْحَقِيبَةِ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">ضَمِيرَا الْغَائِبِ: هُوَ وَهِيَ</span><span class="rule-term-ru">местоимения «он/оно» и «она»</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">هِيَ</span><span class="rule-term-ru">женского</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">كِتَابٌ</span><span class="rule-term-ru">мужского рода, سَيَّارَةٌ — женского</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَيْنَ</span><span class="rule-term-ru">где?: вопросительное имя места</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">ضَمِيرٌ</span><span class="rule-term-ru">местоимение</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">أَيْنَ الْقَلَمُ؟ هُوَ فِي الْحَقِيبَةِ.</span><span class="rule-example-ru">Где ручка? Она в сумке.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">أَيْنَ السَّاعَةُ؟ هِيَ عَلَى السَّرِيرِ.</span><span class="rule-example-ru">Где часы? Они на кровати.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>هُوَ</b> заменяет существительное мужского рода, <b>هِيَ</b> — женского. В арабском грамматический род не всегда совпадает с русским: <b>كِتَابٌ</b> — мужского рода, <b>سَيَّارَةٌ</b> — женского.<br><br><ul><li><b>أَيْنَ الْقَلَمُ؟ هُوَ فِي الْحَقِيبَةِ.</b> — Где ручка? Она в сумке.</li><li><b>أَيْنَ السَّاعَةُ؟ هِيَ عَلَى السَّرِيرِ.</b> — Где часы? Они на кровати.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 3, 'rule', 'Название и смысл ضَمِيرَا الْغَائِبِ: هُوَ وَهِيَ местоимения «он/оно» и «она». هُوَ заменяет существительное мужского рода, هِيَ — женского. В арабском грамматический род не всегда совпадает с русским: كِتَابٌ — мужского рода, سَيَّارَةٌ —'),
('Мединский курс (Том 1)', '4', 'الْمُؤَنَّثُ وَالتَّاءُ الْمَرْبُوطَةُ (женский род и ة)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمُؤَنَّثُ وَالتَّاءُ الْمَرْبُوطَةُ</span><p class="rule-study-text">женский род и ة. Большинство слов с ة относятся к женскому роду: سَيَّارَةٌ، غُرْفَةٌ . Но женский род может быть и без ة , а наличие ة не является единственным возможным признаком.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُؤَنَّثُ وَالتَّاءُ الْمَرْبُوطَةُ</span><span class="rule-term-ru">женский род и ة</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок отдельно.</li><li>Сравните русский смысл с примером.</li><li>Проверьте роль слов и их окончание.</li></ol></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">Большинство слов с <b>ة</b> относятся к женскому роду: <b>سَيَّارَةٌ، غُرْفَةٌ</b>. Но женский род может быть и без <b>ة</b>, а наличие <b>ة</b> не является единственным возможным признаком.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не переводите правило отдельно от арабского примера: форма слова видна именно в предложении.</div></div>', 4, 'rule', 'Название и смысл الْمُؤَنَّثُ وَالتَّاءُ الْمَرْبُوطَةُ женский род и ة. Большинство слов с ة относятся к женскому роду: سَيَّارَةٌ، غُرْفَةٌ . Но женский род может быть и без ة , а наличие ة не является единственным возможным признаком. Ар'),
('Мединский курс (Том 1)', '4', 'ضَمِيرَا الْمُتَكَلِّمِ وَالْمُخَاطَبِ: أَنَا وَأَنْتَ (местоимения «я» и «ты» к мужчине)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">ضَمِيرَا الْمُتَكَلِّمِ وَالْمُخَاطَبِ: أَنَا وَأَنْتَ</span><p class="rule-study-text">местоимения «я» и «ты» к мужчине. أَنَا مُحَمَّدٌ. — Я Мухаммад. أَنْتَ طَالِبٌ. — Ты студент.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">ضَمِيرَا الْمُتَكَلِّمِ وَالْمُخَاطَبِ: أَنَا وَأَنْتَ</span><span class="rule-term-ru">местоимения «я» и «ты» к мужчине</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">ضَمِيرٌ</span><span class="rule-term-ru">местоимение</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите лицо: говорящий, собеседник или отсутствующий.</li><li>Определите число и род.</li><li>Проверьте: местоимение самостоятельное или присоединённое к слову.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">أَنَا مُحَمَّدٌ.</span><span class="rule-example-ru">Я Мухаммад.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">أَنْتَ طَالِبٌ.</span><span class="rule-example-ru">Ты студент.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>أَنَا مُحَمَّدٌ.</b> — Я Мухаммад.</li><li><b>أَنْتَ طَالِبٌ.</b> — Ты студент.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте самостоятельные ضَمَائِرُ مُنْفَصِلَةٌ с присоединёнными ضَمَائِرُ مُتَّصِلَةٌ.</div></div>', 5, 'rule', 'Название и смысл ضَمِيرَا الْمُتَكَلِّمِ وَالْمُخَاطَبِ: أَنَا وَأَنْتَ местоимения «я» и «ты» к мужчине. أَنَا مُحَمَّدٌ. — Я Мухаммад. أَنْتَ طَالِبٌ. — Ты студент. Арабские слова → русский смысл ضَمِيرَا الْمُتَكَلِّمِ وَالْمُخَاطَبِ: أَ'),
('Мединский курс (Том 1)', '4', 'الْفِعْلُ الْمَاضِي لِلْمُفْرَدِ الْمُذَكَّرِ: ذَهَبَ (прошедшее время, «он пошёл»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْفِعْلُ الْمَاضِي لِلْمُفْرَدِ الْمُذَكَّرِ: ذَهَبَ</span><p class="rule-study-text">прошедшее время, «он пошёл». ذَهَبَ означает «он пошёл». Если названо лицо, отдельное هُوَ не требуется: ذَهَبَ بِلَالٌ — «Биляль пошёл».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">الْفِعْلُ الْمَاضِي لِلْمُفْرَدِ الْمُذَكَّرِ: ذَهَبَ</span><span class="rule-term-ru">прошедшее время, «он пошёл»</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">ذَهَبَ بِلَالٌ</span><span class="rule-term-ru">«Биляль пошёл»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите лицо: говорящий, собеседник или отсутствующий.</li><li>Определите число и род.</li><li>Проверьте: местоимение самостоятельное или присоединённое к слову.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">Если названо лицо, отдельное هُوَ не требуется: ذَهَبَ بِلَالٌ</span><span class="rule-example-ru">«Биляль пошёл».</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>ذَهَبَ</b> означает «он пошёл». Если названо лицо, отдельное <b>هُوَ</b> не требуется: <b>ذَهَبَ بِلَالٌ</b> — «Биляль пошёл».</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте самостоятельные ضَمَائِرُ مُنْفَصِلَةٌ с присоединёнными ضَمَائِرُ مُتَّصِلَةٌ.</div></div>', 6, 'rule', 'Название и смысл الْفِعْلُ الْمَاضِي لِلْمُفْرَدِ الْمُذَكَّرِ: ذَهَبَ прошедшее время, «он пошёл». ذَهَبَ означает «он пошёл». Если названо лицо, отдельное هُوَ не требуется: ذَهَبَ بِلَالٌ — «Биляль пошёл». Арабские слова → русский смысл '),
('Мединский курс (Том 1)', '4', 'أَقْسَامُ الْكَلِمَةِ: اِسْمٌ، فِعْلٌ، حَرْفٌ (три вида слова)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَقْسَامُ الْكَلِمَةِ: اِسْمٌ، فِعْلٌ، حَرْفٌ</span><p class="rule-study-text">три вида слова. В объяснениях учителя отдельно выделено деление арабских слов на три основы: اِسْمٌ , فِعْلٌ , حَرْفٌ . اِسْمٌ — имя: существительное, прилагательное, местоимение, указательное или вопросительное имя. فِعْلٌ — глагол: слово действия, связанное со временем. حَرْفٌ — частица/служебное слово: его смысл раскрывается вместе с другим словом.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">أَقْسَامُ الْكَلِمَةِ: اِسْمٌ، فِعْلٌ، حَرْفٌ</span><span class="rule-term-ru">три вида слова</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمٌ</span><span class="rule-term-ru">имя: существительное, прилагательное, местоимение или другое именное слово</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">حَرْفٌ</span><span class="rule-term-ru">частица / служебное слово</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فِعْلٌ</span><span class="rule-term-ru">глагол: слово действия, связанное со временем</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">ذَهَبَ مُحَمَّدٌ إِلَى الْمَدْرَسَةِ</span><span class="rule-term-ru">Мухаммад пошёл в школу</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">اِسْمٌ</span><span class="rule-example-ru">имя: существительное, прилагательное, местоимение, указательное или вопросительное имя.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">فِعْلٌ</span><span class="rule-example-ru">глагол: слово действия, связанное со временем.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">حَرْفٌ</span><span class="rule-example-ru">частица/служебное слово: его смысл раскрывается вместе с другим словом.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">ذَهَبَ مُحَمَّدٌ إِلَى الْمَدْرَسَةِ</span><span class="rule-example-ru">Мухаммад пошёл в школу.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><p>В объяснениях учителя отдельно выделено деление арабских слов на три основы: <b>اِسْمٌ</b>, <b>فِعْلٌ</b>, <b>حَرْفٌ</b>.</p><ul><li><b>اِسْمٌ</b> — имя: существительное, прилагательное, местоимение, указательное или вопросительное имя.</li><li><b>فِعْلٌ</b> — глагол: слово действия, связанное со временем.</li><li><b>حَرْفٌ</b> — частица/служебное слово: его смысл раскрывается вместе с другим словом.</li><li>ذَهَبَ مُحَمَّدٌ إِلَى الْمَدْرَسَةِ — Мухаммад пошёл в школу.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 7, 'rule', 'Название и смысл أَقْسَامُ الْكَلِمَةِ: اِسْمٌ، فِعْلٌ، حَرْفٌ три вида слова. В объяснениях учителя отдельно выделено деление арабских слов на три основы: اِسْمٌ , فِعْلٌ , حَرْفٌ . اِسْمٌ — имя: существительное, прилагательное, местоимени'),
('Мединский курс (Том 1)', '5', 'الْإِضَافَةُ: الْمُضَافُ وَالْمُضَافُ إِلَيْهِ (конструкция принадлежности)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْإِضَافَةُ: الْمُضَافُ وَالْمُضَافُ إِلَيْهِ</span><p class="rule-study-text">конструкция принадлежности. В сочетании «книга Биляля» сначала ставится предмет, затем владелец: كِتَابُ بِلَالٍ . Первое слово — مُضَافٌ , второе — مُضَافٌ إِلَيْهِ . Правила: 1. مُضَافٌ не принимает أَلْـ и танвин.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">الْإِضَافَةُ: الْمُضَافُ وَالْمُضَافُ إِلَيْهِ</span><span class="rule-term-ru">конструкция принадлежности</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مُضَافٌ</span><span class="rule-term-ru">первый член идафы</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">مُضَافٌ إِلَيْهِ</span><span class="rule-term-ru">второй член идафы, всегда مَجْرُورٌ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">بَيْتُ الْإِمَامِ</span><span class="rule-term-ru">дом имама</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">это / этот: указательное имя для близкого мужского рода</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَلْـ</span><span class="rule-term-ru">определённый артикль</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите два имени, связанные смыслом принадлежности.</li><li>Первое имя - مُضَافٌ: без танвина и без أَلْـ.</li><li>Второе имя - مُضَافٌ إِلَيْهِ: всегда в جَرّ.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا كِتَابُ الطَّالِبِ.</span><span class="rule-example-ru">Это книга студента.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">بَابُ الْفَصْلِ مَفْتُوحٌ.</span><span class="rule-example-ru">Дверь класса открыта.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">مِفْتَاحُ السَّيَّارَةِ عَلَى الْمَكْتَبِ.</span><span class="rule-example-ru">Ключ от машины на столе.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">В сочетании «книга Биляля» сначала ставится предмет, затем владелец: <b>كِتَابُ بِلَالٍ</b>. Первое слово — <b>مُضَافٌ</b>, второе — <b>مُضَافٌ إِلَيْهِ</b>.<br><br>Правила:<br><br>1. <b>مُضَافٌ</b> не принимает <b>أَلْـ</b> и танвин.<br>2. <b>مُضَافٌ إِلَيْهِ</b> всегда стоит в родительном падеже.<br>3. Вся конструкция определённая, если владелец определён: <b>بَيْتُ الْإِمَامِ</b> — дом имама.<br><br><ul><li><b>هَذَا كِتَابُ الطَّالِبِ.</b> — Это книга студента.</li><li><b>بَابُ الْفَصْلِ مَفْتُوحٌ.</b> — Дверь класса открыта.</li><li><b>مِفْتَاحُ السَّيَّارَةِ عَلَى الْمَكْتَبِ.</b> — Ключ от машины на столе.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Главная ошибка: дать первому члену идафы танвин или артикль одновременно с идафой.</div></div>', 1, 'rule', 'Название и смысл الْإِضَافَةُ: الْمُضَافُ وَالْمُضَافُ إِلَيْهِ конструкция принадлежности. В сочетании «книга Биляля» сначала ставится предмет, затем владелец: كِتَابُ بِلَالٍ . Первое слово — مُضَافٌ , второе — مُضَافٌ إِلَيْهِ . Правила:'),
('Мединский курс (Том 1)', '5', 'حَرْفُ النِّدَاءِ: يَا (обращение с يَا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">حَرْفُ النِّدَاءِ: يَا</span><p class="rule-study-text">обращение с يَا. При обращении к одному человеку по имени: يَا بِلَالُ . В учебной модели имя после يَا получает одну дамму, а не танвин. يَا مُحَمَّدُ، أَيْنَ كِتَابُكَ؟ — Мухаммад, где твоя книга?</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">حَرْفُ النِّدَاءِ: يَا</span><span class="rule-term-ru">обращение с يَا</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَيْنَ</span><span class="rule-term-ru">где?: вопросительное имя места</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">حَرْفٌ</span><span class="rule-term-ru">частица / служебное слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок отдельно.</li><li>Сравните русский смысл с примером.</li><li>Проверьте роль слов и их окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">يَا مُحَمَّدُ، أَيْنَ كِتَابُكَ؟</span><span class="rule-example-ru">Мухаммад, где твоя книга?</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">При обращении к одному человеку по имени: <b>يَا بِلَالُ</b>. В учебной модели имя после <b>يَا</b> получает одну дамму, а не танвин.<br><br><ul><li><b>يَا مُحَمَّدُ، أَيْنَ كِتَابُكَ؟</b> — Мухаммад, где твоя книга?</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не переводите правило отдельно от арабского примера: форма слова видна именно в предложении.</div></div>', 2, 'rule', 'Название и смысл حَرْفُ النِّدَاءِ: يَا обращение с يَا. При обращении к одному человеку по имени: يَا بِلَالُ . В учебной модели имя после يَا получает одну дамму, а не танвин. يَا مُحَمَّدُ، أَيْنَ كِتَابُكَ؟ — Мухаммад, где твоя книга? А'),
('Мединский курс (Том 1)', '5', 'اِبْنٌ بَيْنَ عَلَمَيْنِ (слово «сын» между двумя именами)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">اِبْنٌ بَيْنَ عَلَمَيْنِ</span><p class="rule-study-text">слово «сын» между двумя именами. Если اِبْنُ находится между именем человека и именем его отца, начальная алиф на письме обычно опускается: مُحَمَّدُ بْنُ عَبْدِ اللَّهِ . Это отдельное орфографическое правило; не следует превращать его в общую замену слова اِبْنٌ .</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">اِبْنٌ بَيْنَ عَلَمَيْنِ</span><span class="rule-term-ru">слово «сын» между двумя именами</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок отдельно.</li><li>Сравните русский смысл с примером.</li><li>Проверьте роль слов и их окончание.</li></ol></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">Если <b>اِبْنُ</b> находится между именем человека и именем его отца, начальная алиф на письме обычно опускается: <b>مُحَمَّدُ بْنُ عَبْدِ اللَّهِ</b>. Это отдельное орфографическое правило; не следует превращать его в общую замену слова <b>اِبْنٌ</b>.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не переводите правило отдельно от арабского примера: форма слова видна именно в предложении.</div></div>', 3, 'rule', 'Название и смысл اِبْنٌ بَيْنَ عَلَمَيْنِ слово «сын» между двумя именами. Если اِبْنُ находится между именем человека и именем его отца, начальная алиф на письме обычно опускается: مُحَمَّدُ بْنُ عَبْدِ اللَّهِ . Это отдельное орфографичес'),
('Мединский курс (Том 1)', '6', 'اِسْمُ الْإِشَارَةِ لِلْمُفْرَدَةِ الْمُؤَنَّثَةِ الْقَرِيبَةِ: هَذِهِ (указательное слово «эта»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">اِسْمُ الْإِشَارَةِ لِلْمُفْرَدَةِ الْمُؤَنَّثَةِ الْقَرِيبَةِ: هَذِهِ</span><p class="rule-study-text">указательное слово «эта». هَذِهِ سَيَّارَةٌ. — Это машина. مَا هَذِهِ؟ هَذِهِ مِلْعَقَةٌ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذِهِ</span><span class="rule-term-ru">эта: указательное имя для близкого женского рода</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمٌ</span><span class="rule-term-ru">имя: существительное, прилагательное, местоимение или другое именное слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">هَذِهِ سَيَّارَةٌ.</span><span class="rule-example-ru">Это машина.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَا هَذِهِ؟ هَذِهِ مِلْعَقَةٌ.</span><span class="rule-example-ru">Что это? Это ложка.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>هَذِهِ سَيَّارَةٌ.</b> — Это машина.</li><li><b>مَا هَذِهِ؟ هَذِهِ مِلْعَقَةٌ.</b> — Что это? Это ложка.</li></ul><br><br>В <b>هَذِهِ</b> алиф после <b>هَاء</b> произносится, но отдельно не пишется. Конечная <b>ـهِ</b> произносится с кратким <b>и</b>.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 1, 'rule', 'Название и смысл اِسْمُ الْإِشَارَةِ لِلْمُفْرَدَةِ الْمُؤَنَّثَةِ الْقَرِيبَةِ: هَذِهِ указательное слово «эта». هَذِهِ سَيَّارَةٌ. — Это машина. مَا هَذِهِ؟ هَذِهِ مِلْعَقَةٌ. Арабские слова → русский смысл هَذِهِ эта: указательное имя дл'),
('Мединский курс (Том 1)', '6', 'تَأْنِيثُ الِاسْمِ وَالصِّفَةِ بِالتَّاءِ الْمَرْبُوطَةِ (образование женского рода)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">تَأْنِيثُ الِاسْمِ وَالصِّفَةِ بِالتَّاءِ الْمَرْبُوطَةِ</span><p class="rule-study-text">образование женского рода. Часто женская форма образуется добавлением ة : مُدَرِّسٌ ← مُدَرِّسَةٌ , جَدِيدٌ ← جَدِيدَةٌ . هَذَا وَلَدٌ صَغِيرٌ. وَهَذِهِ بِنْتٌ صَغِيرَةٌ. — Это маленький мальчик, а это маленькая девочка.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">تَأْنِيثُ الِاسْمِ وَالصِّفَةِ بِالتَّاءِ الْمَرْبُوطَةِ</span><span class="rule-term-ru">образование женского рода</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ة</span><span class="rule-term-ru">مُدَرِّسٌ ← مُدَرِّسَةٌ , جَدِيدٌ ← جَدِيدَةٌ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">это / этот: указательное имя для близкого мужского рода</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذِهِ</span><span class="rule-term-ru">эта: указательное имя для близкого женского рода</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمٌ</span><span class="rule-term-ru">имя: существительное, прилагательное, местоимение или другое именное слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите مَنْعُوتٌ - определяемое слово.</li><li>После него поставьте نَعْتٌ.</li><li>Согласуйте نَعْتٌ с مَنْعُوتٌ в роде, числе, падеже и определённости.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا وَلَدٌ صَغِيرٌ. وَهَذِهِ بِنْتٌ صَغِيرَةٌ.</span><span class="rule-example-ru">Это маленький мальчик, а это маленькая девочка.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">Часто женская форма образуется добавлением <b>ة</b>: <b>مُدَرِّسٌ ← مُدَرِّسَةٌ</b>, <b>جَدِيدٌ ← جَدِيدَةٌ</b>.<br><br><ul><li><b>هَذَا وَلَدٌ صَغِيرٌ. وَهَذِهِ بِنْتٌ صَغِيرَةٌ.</b> — Это маленький мальчик, а это маленькая девочка.</li></ul><br><br>Не каждое слово образует женский род механически; формы нужно сверять со словарём.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Если существительное определённое, прилагательное тоже должно быть определённым; если оно после предлога, прилагательное тоже в جَرّ.</div></div>', 2, 'rule', 'Название и смысл تَأْنِيثُ الِاسْمِ وَالصِّفَةِ بِالتَّاءِ الْمَرْبُوطَةِ образование женского рода. Часто женская форма образуется добавлением ة : مُدَرِّسٌ ← مُدَرِّسَةٌ , جَدِيدٌ ← جَدِيدَةٌ . هَذَا وَلَدٌ صَغِيرٌ. وَهَذِهِ بِنْتٌ صَغِير'),
('Мединский курс (Том 1)', '6', 'أَسْمَاءُ أَعْضَاءِ الْجِسْمِ الْمُزْدَوِجَةِ (названия парных частей тела)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَسْمَاءُ أَعْضَاءِ الْجِسْمِ الْمُزْدَوِجَةِ</span><p class="rule-study-text">названия парных частей тела. В учебнике отмечается, что многие названия парных частей тела женского рода: يَدٌ، رِجْلٌ، عَيْنٌ، أُذُنٌ . Это полезное наблюдение, но не универсальный закон для любого «парного предмета».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَسْمَاءُ أَعْضَاءِ الْجِسْمِ الْمُزْدَوِجَةِ</span><span class="rule-term-ru">названия парных частей тела</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمٌ</span><span class="rule-term-ru">имя: существительное, прилагательное, местоимение или другое именное слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок отдельно.</li><li>Сравните русский смысл с примером.</li><li>Проверьте роль слов и их окончание.</li></ol></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">В учебнике отмечается, что многие названия парных частей тела женского рода: <b>يَدٌ، رِجْلٌ، عَيْنٌ، أُذُنٌ</b>. Это полезное наблюдение, но не универсальный закон для любого «парного предмета».</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не переводите правило отдельно от арабского примера: форма слова видна именно в предложении.</div></div>', 3, 'rule', 'Название и смысл أَسْمَاءُ أَعْضَاءِ الْجِسْمِ الْمُزْدَوِجَةِ названия парных частей тела. В учебнике отмечается, что многие названия парных частей тела женского рода: يَدٌ، رِجْلٌ، عَيْنٌ، أُذُنٌ . Это полезное наблюдение, но не универсал'),
('Мединский курс (Том 1)', '6', 'الْجُمْلَةُ الِاسْمِيَّةُ: الْمُبْتَدَأُ وَالْخَبَرُ (именное предложение: мубтада и хабар)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْجُمْلَةُ الِاسْمِيَّةُ: الْمُبْتَدَأُ وَالْخَبَرُ</span><p class="rule-study-text">именное предложение: мубтада и хабар. الْجُمْلَةُ الِاسْمِيَّةُ — именное предложение. В шархе первого тома это правило появляется в шестом уроке: предложение начинается с имени и состоит из двух главных частей. الْمُبْتَدَأُ — первый член именного предложения; то, о чём говорится. В основе он مَرْفُوعٌ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">الْجُمْلَةُ الِاسْمِيَّةُ: الْمُبْتَدَأُ وَالْخَبَرُ</span><span class="rule-term-ru">именное предложение: мубтада и хабар</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الْجُمْلَةُ الِاسْمِيَّةُ</span><span class="rule-term-ru">именное предложение</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُبْتَدَأُ</span><span class="rule-term-ru">подлежащее именного предложения; первый главный член الجُمْلَةُ الِاسْمِيَّةُ</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar" dir="rtl" lang="ar">الْخَبَرُ</span><span class="rule-term-ru">сказуемое / сообщение о الْمُبْتَدَأُ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا طَالِبٌ</span><span class="rule-term-ru">Это студент</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذِهِ طَالِبَةٌ</span><span class="rule-term-ru">Это студентка</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَحْمَدُ مُدَرِّسٌ</span><span class="rule-term-ru">Ахмад — преподаватель</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">آمِنَةُ طَبِيبَةٌ</span><span class="rule-term-ru">Амина — врач</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">إِعْرَابٌ مُبَسَّطٌ</span><span class="rule-term-ru">в примере هَذَا طَالِبٌ слово هَذَا стоит в позиции مُبْتَدَأٌ, а طَالِبٌ является خَبَرٌ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">طَالِبٌ</span><span class="rule-term-ru">дамма/танвин даммы в конце</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">это / этот: указательное имя для близкого мужского рода</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذِهِ</span><span class="rule-term-ru">эта: указательное имя для близкого женского рода</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите مُبْتَدَأٌ: о ком или о чём говорится.</li><li>Найдите خَبَرٌ: что сообщается.</li><li>Оба главных члена обычно مَرْفُوعٌ.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">الْمُبْتَدَأُ</span><span class="rule-example-ru">первый член именного предложения; то, о чём говорится. В основе он مَرْفُوعٌ.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">الْخَبَرُ</span><span class="rule-example-ru">второй член именного предложения; сообщение о مُبْتَدَأٌ. В основе он тоже مَرْفُوعٌ.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا طَالِبٌ</span><span class="rule-example-ru">Это студент.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">هَذِهِ طَالِبَةٌ</span><span class="rule-example-ru">Это студентка.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">أَحْمَدُ مُدَرِّسٌ</span><span class="rule-example-ru">Ахмад — преподаватель.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">آمِنَةُ طَبِيبَةٌ</span><span class="rule-example-ru">Амина — врач.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><p><b>الْجُمْلَةُ الِاسْمِيَّةُ</b> — именное предложение. В шархе первого тома это правило появляется в шестом уроке: предложение начинается с имени и состоит из двух главных частей.</p><ul><li><b>الْمُبْتَدَأُ</b> — первый член именного предложения; то, о чём говорится. В основе он مَرْفُوعٌ.</li><li><b>الْخَبَرُ</b> — второй член именного предложения; сообщение о مُبْتَدَأٌ. В основе он тоже مَرْفُوعٌ.</li><li>هَذَا طَالِبٌ — Это студент.</li><li>هَذِهِ طَالِبَةٌ — Это студентка.</li><li>أَحْمَدُ مُدَرِّسٌ — Ахмад — преподаватель.</li><li>آمِنَةُ طَبِيبَةٌ — Амина — врач.</li></ul><p><b>إِعْرَابٌ مُبَسَّطٌ:</b> в примере <b>هَذَا طَالِبٌ</b> слово <b>هَذَا</b> стоит в позиции مُبْتَدَأٌ, а <b>طَالِبٌ</b> является خَبَرٌ; признак رفع у <b>طَالِبٌ</b> — дамма/танвин даммы в конце.</p></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не называйте любое первое слово مُبْتَدَأٌ автоматически: сначала проверьте, даёт ли второе слово законченное сообщение.</div></div>', 4, 'rule', 'Название и смысл الْجُمْلَةُ الِاسْمِيَّةُ: الْمُبْتَدَأُ وَالْخَبَرُ именное предложение: мубтада и хабар. الْجُمْلَةُ الِاسْمِيَّةُ — именное предложение. В шархе первого тома это правило появляется в шестом уроке: предложение начинается '),
('Мединский курс (Том 1)', '6', 'لِـ، لِمَنْ؟ (принадлежность с предлогом لِـ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">لِـ، لِمَنْ؟</span><p class="rule-study-text">принадлежность с предлогом لِـ. لِـ означает «принадлежит/для». После него существительное в родительном падеже. الْكِتَابُ لِبِلَالٍ. — Книга принадлежит Билялю.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لِـ، لِمَنْ؟</span><span class="rule-term-ru">принадлежность с предлогом لِـ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">это / этот: указательное имя для близкого мужского рода</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">الْكِتَابُ لِبِلَالٍ.</span><span class="rule-example-ru">Книга принадлежит Билялю.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">لِمَنْ هَذَا الْقَلَمُ؟ هُوَ لِلْمُدَرِّسِ.</span><span class="rule-example-ru">Чья это ручка? Она принадлежит учителю.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">الْحَمْدُ لِلَّهِ.</span><span class="rule-example-ru">Хвала Аллаху. В сочетании لِـ + اللَّهُ начальная алиф опускается: لِلَّهِ .</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>لِـ</b> означает «принадлежит/для». После него существительное в родительном падеже.<br><br><ul><li><b>الْكِتَابُ لِبِلَالٍ.</b> — Книга принадлежит Билялю.</li><li><b>لِمَنْ هَذَا الْقَلَمُ؟ هُوَ لِلْمُدَرِّسِ.</b> — Чья это ручка? Она принадлежит учителю.</li><li><b>الْحَمْدُ لِلَّهِ.</b> — Хвала Аллаху. В сочетании <b>لِـ + اللَّهُ</b> начальная алиф опускается: <b>لِلَّهِ</b>.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 5, 'rule', 'Название и смысл لِـ، لِمَنْ؟ принадлежность с предлогом لِـ. لِـ означает «принадлежит/для». После него существительное в родительном падеже. الْكِتَابُ لِبِلَالٍ. — Книга принадлежит Билялю. Арабские слова → русский смысл لِـ، لِمَنْ؟ при'),
('Мединский курс (Том 1)', '6', 'جِدًّا (наречие «очень»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">جِدًّا</span><p class="rule-study-text">наречие «очень». هَذَا جَمِيلٌ جِدًّا. — Это очень красиво. هَذِهِ سَيَّارَةٌ جَمِيلَةٌ جِدًّا. — Это очень красивая машина.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">جِدًّا</span><span class="rule-term-ru">наречие «очень»</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">это / этот: указательное имя для близкого мужского рода</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذِهِ</span><span class="rule-term-ru">эта: указательное имя для близкого женского рода</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا جَمِيلٌ جِدًّا.</span><span class="rule-example-ru">Это очень красиво.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">هَذِهِ سَيَّارَةٌ جَمِيلَةٌ جِدًّا.</span><span class="rule-example-ru">Это очень красивая машина.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>هَذَا جَمِيلٌ جِدًّا.</b> — Это очень красиво.</li><li><b>هَذِهِ سَيَّارَةٌ جَمِيلَةٌ جِدًّا.</b> — Это очень красивая машина.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 6, 'rule', 'Название и смысл جِدًّا наречие «очень». هَذَا جَمِيلٌ جِدًّا. — Это очень красиво. هَذِهِ سَيَّارَةٌ جَمِيلَةٌ جِدًّا. — Это очень красивая машина. Арабские слова → русский смысл جِدًّا наречие «очень» هَذَا это / этот: указательное имя дл'),
('Мединский курс (Том 1)', '7', 'اِسْمُ الْإِشَارَةِ لِلْمُفْرَدَةِ الْمُؤَنَّثَةِ الْبَعِيدَةِ: تِلْكَ (указательное слово «та»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">اِسْمُ الْإِشَارَةِ لِلْمُفْرَدَةِ الْمُؤَنَّثَةِ الْبَعِيدَةِ: تِلْكَ</span><p class="rule-study-text">указательное слово «та». تِلْكَ указывает на один удалённый предмет женского рода. هَذِهِ آمِنَةُ وَتِلْكَ مَرْيَمُ. — Это Амина, а та — Марьям. مَا تِلْكَ؟</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">تِلْكَ</span><span class="rule-term-ru">неизменяемое указательное слово</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذِهِ</span><span class="rule-term-ru">эта: указательное имя для близкого женского рода</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمٌ</span><span class="rule-term-ru">имя: существительное, прилагательное, местоимение или другое именное слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">هَذِهِ آمِنَةُ وَتِلْكَ مَرْيَمُ.</span><span class="rule-example-ru">Это Амина, а та — Марьям.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَا تِلْكَ؟ تِلْكَ نَاقَةٌ.</span><span class="rule-example-ru">Что там? Там верблюдица.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>تِلْكَ</b> указывает на один удалённый предмет женского рода.<br><br><ul><li><b>هَذِهِ آمِنَةُ وَتِلْكَ مَرْيَمُ.</b> — Это Амина, а та — Марьям.</li><li><b>مَا تِلْكَ؟ تِلْكَ نَاقَةٌ.</b> — Что там? Там верблюдица.</li></ul><br><br><b>Дополнительное объяснение:</b> <b>تِلْكَ</b> — неизменяемое указательное слово; его роль определяется местом в предложении.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 1, 'rule', 'Название и смысл اِسْمُ الْإِشَارَةِ لِلْمُفْرَدَةِ الْمُؤَنَّثَةِ الْبَعِيدَةِ: تِلْكَ указательное слово «та». تِلْكَ указывает на один удалённый предмет женского рода. هَذِهِ آمِنَةُ وَتِلْكَ مَرْيَمُ. — Это Амина, а та — Марьям. مَا تِل'),
('Мединский курс (Том 1)', '8', 'اِسْمُ الْإِشَارَةِ مَعَ الِاسْمِ الْمُعَرَّفِ (указательное слово + определённое существительное)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">اِسْمُ الْإِشَارَةِ مَعَ الِاسْمِ الْمُعَرَّفِ</span><p class="rule-study-text">указательное слово + определённое существительное. هَذَا كِتَابٌ — законченное предложение «Это книга». هَذَا الْكِتَابُ — сочетание «эта книга» и само по себе обычно не является законченным сообщением. هَذَا الْكِتَابُ جَدِيدٌ. — Эта книга новая.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمُ الْإِشَارَةِ مَعَ الِاسْمِ الْمُعَرَّفِ</span><span class="rule-term-ru">указательное слово + определённое существительное</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا كِتَابٌ</span><span class="rule-term-ru">законченное предложение «Это книга»</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا الْكِتَابُ</span><span class="rule-term-ru">сочетание «эта книга» и само по себе обычно не является законченным сообщением</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">это / этот: указательное имя для близкого мужского рода</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذِهِ</span><span class="rule-term-ru">эта: указательное имя для близкого женского рода</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ذَلِكَ</span><span class="rule-term-ru">то / тот: указательное имя для далёкого мужского рода</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمٌ</span><span class="rule-term-ru">имя: существительное, прилагательное, местоимение или другое именное слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا الْكِتَابُ جَدِيدٌ.</span><span class="rule-example-ru">Эта книга новая.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">ذَلِكَ الرَّجُلُ مُهَنْدِسٌ.</span><span class="rule-example-ru">Тот мужчина — инженер.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">هَذِهِ السَّيَّارَةُ جَمِيلَةٌ.</span><span class="rule-example-ru">Эта машина красивая.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>هَذَا كِتَابٌ</b> — законченное предложение «Это книга». <b>هَذَا الْكِتَابُ</b> — сочетание «эта книга» и само по себе обычно не является законченным сообщением.<br><br><ul><li><b>هَذَا الْكِتَابُ جَدِيدٌ.</b> — Эта книга новая.</li><li><b>ذَلِكَ الرَّجُلُ مُهَنْدِسٌ.</b> — Тот мужчина — инженер.</li><li><b>هَذِهِ السَّيَّارَةُ جَمِيلَةٌ.</b> — Эта машина красивая.</li></ul><br><br><b>Дополнительное объяснение.</b> Определённое существительное после указательного слова можно разбирать как <b>بَدَلٌ</b> или <b>عَطْفُ بَيَانٍ</b>. В тренажёре достаточно пометить его как поясняющее существительное; нельзя называть всё сочетание обычным «подлежащее + сказуемое».</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 1, 'rule', 'Название и смысл اِسْمُ الْإِشَارَةِ مَعَ الِاسْمِ الْمُعَرَّفِ указательное слово + определённое существительное. هَذَا كِتَابٌ — законченное предложение «Это книга». هَذَا الْكِتَابُ — сочетание «эта книга» и само по себе обычно не являет'),
('Мединский курс (Том 1)', '8', 'الِاسْمُ الْمَقْصُورُ وَالْحَرَكَاتُ الْمُقَدَّرَةُ (слова на алиф и скрытые окончания)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الِاسْمُ الْمَقْصُورُ وَالْحَرَكَاتُ الْمُقَدَّرَةُ</span><p class="rule-study-text">слова на алиф и скрытые окончания. У слов, заканчивающихся на долгий ا/ى , конечная падежная огласовка может быть непроизносимой и считается предполагаемой: الْمُسْتَشْفَى، مُوسَى . هُوَ فِي الْمُسْتَشْفَى. — Он в больнице. Важно: это не означает, что все такие слова неизменяемы.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الِاسْمُ الْمَقْصُورُ وَالْحَرَكَاتُ الْمُقَدَّرَةُ</span><span class="rule-term-ru">слова на алиф и скрытые окончания</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُسْتَشْفَى</span><span class="rule-term-ru">склоняемое слово с предполагаемой касрой после فِي</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَلْـ</span><span class="rule-term-ru">определённый артикль</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمٌ</span><span class="rule-term-ru">имя: существительное, прилагательное, местоимение или другое именное слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">هُوَ فِي الْمُسْتَشْفَى.</span><span class="rule-example-ru">Он в больнице.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">У слов, заканчивающихся на долгий <b>ا/ى</b>, конечная падежная огласовка может быть непроизносимой и считается предполагаемой: <b>الْمُسْتَشْفَى، مُوسَى</b>.<br><br><ul><li><b>هُوَ فِي الْمُسْتَشْفَى.</b> — Он в больнице.</li></ul><br><br>Важно: это не означает, что все такие слова неизменяемы. <b>الْمُسْتَشْفَى</b> — склоняемое слово с предполагаемой касрой после <b>فِي</b>; <b>مُوسَى</b> и <b>أَمْرِيكَا</b> относятся также к несклоняемым по танвину словам и в родительном падеже имеют предполагаемую фатху, если нет <b>أَلْـ</b> и идафы.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 2, 'rule', 'Название и смысл الِاسْمُ الْمَقْصُورُ وَالْحَرَكَاتُ الْمُقَدَّرَةُ слова на алиф и скрытые окончания. У слов, заканчивающихся на долгий ا/ى , конечная падежная огласовка может быть непроизносимой и считается предполагаемой: الْمُسْتَشْفَى'),
('Мединский курс (Том 1)', '8', 'أَمَامَ وَخَلْفَ (обстоятельства места «перед» и «за»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَمَامَ وَخَلْفَ</span><p class="rule-study-text">обстоятельства места «перед» и «за». حَامِدٌ أَمَامَ الْمُدَرِّسِ. — Хамид перед учителем. الْبَيْتُ خَلْفَ الْمَسْجِدِ. — Дом за мечетью.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَمَامَ وَخَلْفَ</span><span class="rule-term-ru">обстоятельства места «перед» и «за»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок отдельно.</li><li>Сравните русский смысл с примером.</li><li>Проверьте роль слов и их окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">حَامِدٌ أَمَامَ الْمُدَرِّسِ.</span><span class="rule-example-ru">Хамид перед учителем.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">الْبَيْتُ خَلْفَ الْمَسْجِدِ.</span><span class="rule-example-ru">Дом за мечетью.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>حَامِدٌ أَمَامَ الْمُدَرِّسِ.</b> — Хамид перед учителем.</li><li><b>الْبَيْتُ خَلْفَ الْمَسْجِدِ.</b> — Дом за мечетью.</li></ul><br><br><b>أَمَامَ</b> и <b>خَلْفَ</b> обычно выступают первым членом идафы; следующее существительное стоит в родительном падеже.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не переводите правило отдельно от арабского примера: форма слова видна именно в предложении.</div></div>', 3, 'rule', 'Название и смысл أَمَامَ وَخَلْفَ обстоятельства места «перед» и «за». حَامِدٌ أَمَامَ الْمُدَرِّسِ. — Хамид перед учителем. الْبَيْتُ خَلْفَ الْمَسْجِدِ. — Дом за мечетью. Арабские слова → русский смысл أَمَامَ وَخَلْفَ обстоятельства мест'),
('Мединский курс (Том 1)', '8', 'الْبَدَلُ بَعْدَ اسْمِ الْإِشَارَةِ (بدل после указательного слова)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْبَدَلُ بَعْدَ اسْمِ الْإِشَارَةِ</span><p class="rule-study-text">بدل после указательного слова. الْبَدَلُ — слово, которое поясняет предыдущее слово и следует за ним в падеже. После указательного слова имя с أَلْـ часто разбирается как بدل. هَذَا الرَّجُلُ تَاجِرٌ — Этот мужчина — торговец. ذَلِكَ الْبَيْتُ قَدِيمٌ — Тот дом старый.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْبَدَلُ بَعْدَ اسْمِ الْإِشَارَةِ</span><span class="rule-term-ru">بدل после указательного слова</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْبَدَلُ</span><span class="rule-term-ru">слово, которое поясняет предыдущее слово и следует за ним в падеже</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا الرَّجُلُ تَاجِرٌ</span><span class="rule-term-ru">Этот мужчина — торговец</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ذَلِكَ الْبَيْتُ قَدِيمٌ</span><span class="rule-term-ru">Тот дом старый</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">اِسْمُ إِشَارَةٍ — указательное имя</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الرَّجُلُ</span><span class="rule-term-ru">بَدَلٌ — بدل, поясняющий هَذَا</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ذَلِكَ</span><span class="rule-term-ru">то / тот: указательное имя для далёкого мужского рода</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَلْـ</span><span class="rule-term-ru">определённый артикль</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمٌ</span><span class="rule-term-ru">имя: существительное, прилагательное, местоимение или другое именное слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا الرَّجُلُ تَاجِرٌ</span><span class="rule-example-ru">Этот мужчина — торговец.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">ذَلِكَ الْبَيْتُ قَدِيمٌ</span><span class="rule-example-ru">Тот дом старый.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا: اِسْمُ إِشَارَةٍ</span><span class="rule-example-ru">указательное имя.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">الرَّجُلُ: بَدَلٌ</span><span class="rule-example-ru">بدل, поясняющий هَذَا.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><p><b>الْبَدَلُ</b> — слово, которое поясняет предыдущее слово и следует за ним в падеже. После указательного слова имя с <b>أَلْـ</b> часто разбирается как بدل.</p><ul><li>هَذَا الرَّجُلُ تَاجِرٌ — Этот мужчина — торговец.</li><li>ذَلِكَ الْبَيْتُ قَدِيمٌ — Тот дом старый.</li><li>هَذَا: اِسْمُ إِشَارَةٍ — указательное имя.</li><li>الرَّجُلُ: بَدَلٌ — بدل, поясняющий هَذَا.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 4, 'rule', 'Название и смысл الْبَدَلُ بَعْدَ اسْمِ الْإِشَارَةِ بدل после указательного слова. الْبَدَلُ — слово, которое поясняет предыдущее слово и следует за ним в падеже. После указательного слова имя с أَلْـ часто разбирается как بدل. هَذَا الرَّ'),
('Мединский курс (Том 1)', '9', 'النَّعْتُ وَالْمَنْعُوتُ (прилагательное и определяемое слово)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">النَّعْتُ وَالْمَنْعُوتُ</span><p class="rule-study-text">прилагательное и определяемое слово. В арабском прилагательное стоит после существительного и согласуется с ним в роде, определённости и падеже; позднее добавится согласование в числе. بَيْتٌ جَدِيدٌ. — Новый дом. Оба слова неопределённые и именительные.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">النَّعْتُ وَالْمَنْعُوتُ</span><span class="rule-term-ru">прилагательное и определяемое слово</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْعُوتٌ</span><span class="rule-term-ru">определяемое слово</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">نَعْتٌ</span><span class="rule-term-ru">прилагательное / определение</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите مَنْعُوتٌ - определяемое слово.</li><li>После него поставьте نَعْتٌ.</li><li>Согласуйте نَعْتٌ с مَنْعُوتٌ в роде, числе, падеже и определённости.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">بَيْتٌ جَدِيدٌ.</span><span class="rule-example-ru">Новый дом. Оба слова неопределённые и именительные.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">سَيَّارَةٌ جَدِيدَةٌ.</span><span class="rule-example-ru">Новая машина. Прилагательное женского рода.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">الْمُدَرِّسُ الْجَدِيدُ فِي الْفَصْلِ.</span><span class="rule-example-ru">Новый учитель в классе. Оба слова определённые.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">أَنَا فِي بَيْتٍ جَدِيدٍ.</span><span class="rule-example-ru">Я в новом доме. Оба слова родительного падежа после فِي .</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">В арабском прилагательное стоит после существительного и согласуется с ним в роде, определённости и падеже; позднее добавится согласование в числе.<br><br><ul><li><b>بَيْتٌ جَدِيدٌ.</b> — Новый дом. Оба слова неопределённые и именительные.</li><li><b>سَيَّارَةٌ جَدِيدَةٌ.</b> — Новая машина. Прилагательное женского рода.</li><li><b>الْمُدَرِّسُ الْجَدِيدُ فِي الْفَصْلِ.</b> — Новый учитель в классе. Оба слова определённые.</li><li><b>أَنَا فِي بَيْتٍ جَدِيدٍ.</b> — Я в новом доме. Оба слова родительного падежа после <b>فِي</b>.</li></ul><br><br><b>Дополнительное объяснение.</b> Существительное — <b>مَنْعُوتٌ</b>, прилагательное — <b>نَعْتٌ</b>. Несогласованность хотя бы по одному признаку меняет структуру или делает фразу ошибочной.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Если существительное определённое, прилагательное тоже должно быть определённым; если оно после предлога, прилагательное тоже в جَرّ.</div></div>', 1, 'rule', 'Название и смысл النَّعْتُ وَالْمَنْعُوتُ прилагательное и определяемое слово. В арабском прилагательное стоит после существительного и согласуется с ним в роде, определённости и падеже; позднее добавится согласование в числе. بَيْتٌ جَدِيد'),
('Мединский курс (Том 1)', '9', 'الصِّفَاتُ الْمُخْتُومَةُ بِـ«ـَانُ» (прилагательные на ـَانُ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الصِّفَاتُ الْمُخْتُومَةُ بِـ«ـَانُ»</span><p class="rule-study-text">прилагательные на ـَانُ. Некоторые прилагательные на ـَانُ не принимают танвин: عَطْشَانُ، جَوْعَانُ، غَضْبَانُ، مَلْآنُ . Их женские формы изучаются как словарные.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الصِّفَاتُ الْمُخْتُومَةُ بِـ«ـَانُ»</span><span class="rule-term-ru">прилагательные на ـَانُ</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Проверьте, что речь ровно о двух предметах или лицах.</li><li>В رَفْع обычно используется окончание ـَانِ.</li><li>В نَصْب и جَرّ используется ـَيْنِ.</li></ol></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">Некоторые прилагательные на <b>ـَانُ</b> не принимают танвин: <b>عَطْشَانُ، جَوْعَانُ، غَضْبَانُ، مَلْآنُ</b>. Их женские формы изучаются как словарные.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя переводить двойственное как обычное множественное: оно означает именно «два / две».</div></div>', 2, 'rule', 'Название и смысл الصِّفَاتُ الْمُخْتُومَةُ بِـ«ـَانُ» прилагательные на ـَانُ. Некоторые прилагательные на ـَانُ не принимают танвин: عَطْشَانُ، جَوْعَانُ، غَضْبَانُ، مَلْآنُ . Их женские формы изучаются как словарные. Арабские слова → русс'),
('Мединский курс (Том 1)', '9', 'الِاسْمُ الْمَوْصُولُ: الَّذِي (относительное слово «который»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الِاسْمُ الْمَوْصُولُ: الَّذِي</span><p class="rule-study-text">относительное слово «который». الَّذِي относится к одному слову мужского рода и вводит придаточное описание. الرَّجُلُ الَّذِي خَرَجَ مِنَ الْمَسْجِدِ تَاجِرٌ. — Мужчина, который вышел из мечети, — торговец. الْبَيْتُ الَّذِي أَمَامَ الْمَسْجِدِ لِلْإِمَامِ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الِاسْمُ الْمَوْصُولُ: الَّذِي</span><span class="rule-term-ru">относительное слово «который»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمٌ</span><span class="rule-term-ru">имя: существительное, прилагательное, местоимение или другое именное слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">الرَّجُلُ الَّذِي خَرَجَ مِنَ الْمَسْجِدِ تَاجِرٌ.</span><span class="rule-example-ru">Мужчина, который вышел из мечети, — торговец.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">الْبَيْتُ الَّذِي أَمَامَ الْمَسْجِدِ لِلْإِمَامِ.</span><span class="rule-example-ru">Дом, который перед мечетью, принадлежит имаму.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>الَّذِي</b> относится к одному слову мужского рода и вводит придаточное описание.<br><br><ul><li><b>الرَّجُلُ الَّذِي خَرَجَ مِنَ الْمَسْجِدِ تَاجِرٌ.</b> — Мужчина, который вышел из мечети, — торговец.</li><li><b>الْبَيْتُ الَّذِي أَمَامَ الْمَسْجِدِ لِلْإِمَامِ.</b> — Дом, который перед мечетью, принадлежит имаму.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 3, 'rule', 'Название и смысл الِاسْمُ الْمَوْصُولُ: الَّذِي относительное слово «который». الَّذِي относится к одному слову мужского рода и вводит придаточное описание. الرَّجُلُ الَّذِي خَرَجَ مِنَ الْمَسْجِدِ تَاجِرٌ. — Мужчина, который вышел из мече'),
('Мединский курс (Том 1)', '9', 'عِنْدَ (значения «у/при/рядом с»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">عِنْدَ</span><p class="rule-study-text">значения «у/при/рядом с». الْمُدَرِّسُ عِنْدَ الْمُدِيرِ. — Учитель у директора, то есть находится у него. Следующее существительное стоит в родительном падеже: عِنْدَ الْمُدِيرِ .</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">عِنْدَ</span><span class="rule-term-ru">значения «у/при/рядом с»</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок отдельно.</li><li>Сравните русский смысл с примером.</li><li>Проверьте роль слов и их окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">الْمُدَرِّسُ عِنْدَ الْمُدِيرِ.</span><span class="rule-example-ru">Учитель у директора, то есть находится у него.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>الْمُدَرِّسُ عِنْدَ الْمُدِيرِ.</b> — Учитель у директора, то есть находится у него.</li></ul><br><br>Следующее существительное стоит в родительном падеже: <b>عِنْدَ الْمُدِيرِ</b>.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не переводите правило отдельно от арабского примера: форма слова видна именно в предложении.</div></div>', 4, 'rule', 'Название и смысл عِنْدَ значения «у/при/рядом с». الْمُدَرِّسُ عِنْدَ الْمُدِيرِ. — Учитель у директора, то есть находится у него. Следующее существительное стоит в родительном падеже: عِنْدَ الْمُدِيرِ . Арабские слова → русский смысл عِنْ'),
('Мединский курс (Том 1)', '9', 'لِـ مَعَ أَلْـ (слияние предлога لِـ с артиклем)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">لِـ مَعَ أَلْـ</span><p class="rule-study-text">слияние предлога لِـ с артиклем. При соединении لِـ с существительным на أَلْـ алиф артикля опускается: لِـ + الْإِمَامِ = لِلْإِمَامِ .</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لِـ مَعَ أَلْـ</span><span class="rule-term-ru">слияние предлога لِـ с артиклем</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَلْـ</span><span class="rule-term-ru">определённый артикль</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок отдельно.</li><li>Сравните русский смысл с примером.</li><li>Проверьте роль слов и их окончание.</li></ol></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">При соединении <b>لِـ</b> с существительным на <b>أَلْـ</b> алиф артикля опускается: <b>لِـ + الْإِمَامِ = لِلْإِمَامِ</b>.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не переводите правило отдельно от арабского примера: форма слова видна именно в предложении.</div></div>', 5, 'rule', 'Название и смысл لِـ مَعَ أَلْـ слияние предлога لِـ с артиклем. При соединении لِـ с существительным на أَلْـ алиф артикля опускается: لِـ + الْإِمَامِ = لِلْإِمَامِ . Арабские слова → русский смысл لِـ مَعَ أَلْـ слияние предлога لِـ с ар'),
('Мединский курс (Том 1)', '10', 'ضَمَائِرُ الْمِلْكِيَّةِ الْمُتَّصِلَةُ (притяжательные суффиксы)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">ضَمَائِرُ الْمِلْكِيَّةِ الْمُتَّصِلَةُ</span><p class="rule-study-text">притяжательные суффиксы. Вводятся ـِي — мой, ـكَ — твой (к мужчине), ـهُ — его, ـهَا — её. Это не самостоятельные слова, а присоединяемые местоимения. كِتَابِي — моя книга. كِتَابُكَ — твоя книга.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ضَمَائِرُ الْمِلْكِيَّةِ الْمُتَّصِلَةُ</span><span class="rule-term-ru">притяжательные суффиксы</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ـِي</span><span class="rule-term-ru">мой, ـكَ — твой (к мужчине), ـهُ — его, ـهَا — её</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">كِتَابِي</span><span class="rule-term-ru">моя книга</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">كِتَابُكَ</span><span class="rule-term-ru">твоя книга</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">كِتَابُهُ</span><span class="rule-term-ru">его книга</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">كِتَابُهَا</span><span class="rule-term-ru">её книга</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">مُبْتَدَأٌ</span><span class="rule-term-ru">подлежащее именного предложения</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar" dir="rtl" lang="ar">خَبَرٌ</span><span class="rule-term-ru">сказуемое / сообщение о مُبْتَدَأٌ</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в именительном падеже / в состоянии رفع</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">كِتَابِي</span><span class="rule-example-ru">моя книга.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">كِتَابُكَ</span><span class="rule-example-ru">твоя книга.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">كِتَابُهُ</span><span class="rule-example-ru">его книга.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">كِتَابُهَا</span><span class="rule-example-ru">её книга.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">Вводятся <b>ـِي</b> — мой, <b>ـكَ</b> — твой (к мужчине), <b>ـهُ</b> — его, <b>ـهَا</b> — её. Это не самостоятельные слова, а присоединяемые местоимения.<br><br><ul><li><b>كِتَابِي</b> — моя книга.</li><li><b>كِتَابُكَ</b> — твоя книга.</li><li><b>كِتَابُهُ</b> — его книга.</li><li><b>كِتَابُهَا</b> — её книга.</li></ul><br><br><h4>Пример с и‘раб-разметкой (включается с урока 10)</h4><br><br><div class="iarab-example" dir="rtl"><br><br><span class="iarab-token role-mubtada"><span class="iarab-word">كِتَابُكَ</span><span class="iarab-label">مُبْتَدَأٌ مَرْفُوعٌ</span></span><br><br><span class="iarab-token role-khabar"><span class="iarab-word">جَدِيدٌ</span><span class="iarab-label">خَبَرٌ مَرْفُوعٌ</span></span><br><br></div><br><br><b>كِتَابُكَ جَدِيدٌ.</b> — Твоя книга новая. Первое слово — мубтада; второе — хабар. Суффикс <b>ـكَ</b> внутри <b>كِتَابُكَ</b> — <b>ضَمِيرٌ مُتَّصِلٌ فِي مَحَلِّ جَرٍّ</b> и выполняет роль второго члена идафы.<br><br>При присоединении суффикса танвин и артикль у существительного не употребляются. Суффикс делает сочетание определённым.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 1, 'rule', 'Название и смысл ضَمَائِرُ الْمِلْكِيَّةِ الْمُتَّصِلَةُ притяжательные суффиксы. Вводятся ـِي — мой, ـكَ — твой (к мужчине), ـهُ — его, ـهَا — её. Это не самостоятельные слова, а присоединяемые местоимения. كِتَابِي — моя книга. كِتَابُكَ '),
('Мединский курс (Том 1)', '10', 'أَبٌ وَأَخٌ فِي الْإِضَافَةِ (слова «отец» и «брат» в идафе)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَبٌ وَأَخٌ فِي الْإِضَافَةِ</span><p class="rule-study-text">слова «отец» и «брат» в идафе. В именительном падеже перед не-йа-суффиксом формы أَبٌ и أَخٌ получают و : أَبُوكَ، أَخُوهُ، أَبُو مُحَمَّدٍ . أَبُوكَ مُدَرِّسٌ. — Твой отец — учитель. أَخُوهُ طَبِيبٌ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَبٌ وَأَخٌ فِي الْإِضَافَةِ</span><span class="rule-term-ru">слова «отец» и «брат» в идафе</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الْأَسْمَاءُ الْخَمْسَةُ</span><span class="rule-term-ru">пять особых имён: أَبٌ، أَخٌ، حَمٌ، فُو، ذُو</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">و</span><span class="rule-term-ru">أَبُوكَ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">يَاءُ الْمُتَكَلِّمِ</span><span class="rule-term-ru">أَبِي</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمٌ</span><span class="rule-term-ru">имя: существительное, прилагательное, местоимение или другое именное слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите два имени, связанные смыслом принадлежности.</li><li>Первое имя - مُضَافٌ: без танвина и без أَلْـ.</li><li>Второе имя - مُضَافٌ إِلَيْهِ: всегда в جَرّ.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أَبُوكَ مُدَرِّسٌ.</span><span class="rule-example-ru">Твой отец — учитель.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">أَخُوهُ طَبِيبٌ.</span><span class="rule-example-ru">Его брат — врач.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">В именительном падеже перед не-йа-суффиксом формы <b>أَبٌ</b> и <b>أَخٌ</b> получают <b>و</b>: <b>أَبُوكَ، أَخُوهُ، أَبُو مُحَمَّدٍ</b>.<br><br><ul><li><b>أَبُوكَ مُدَرِّسٌ.</b> — Твой отец — учитель.</li><li><b>أَخُوهُ طَبِيبٌ.</b> — Его брат — врач.</li></ul><br><br><b>Дополнительное объяснение.</b> Это часть темы <b>الْأَسْمَاءُ الْخَمْسَةُ</b>. Форма зависит от падежа: именительный <b>أَبُوكَ</b>, винительный <b>أَبَاكَ</b>, родительный <b>أَبِيكَ</b>. Перед <b>يَاءُ الْمُتَكَلِّمِ</b>: <b>أَبِي، أَخِي</b>. Нельзя учить правило как «всегда добавляется و».</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Главная ошибка: дать первому члену идафы танвин или артикль одновременно с идафой.</div></div>', 2, 'rule', 'Название и смысл أَبٌ وَأَخٌ فِي الْإِضَافَةِ слова «отец» и «брат» в идафе. В именительном падеже перед не-йа-суффиксом формы أَبٌ и أَخٌ получают و : أَبُوكَ، أَخُوهُ، أَبُو مُحَمَّدٍ . أَبُوكَ مُدَرِّسٌ. — Твой отец — учитель. أَخُوهُ طَ'),
('Мединский курс (Том 1)', '10', 'عِنْدَ مَعَ الضَّمِيرِ لِمَعْنَى الْمِلْكِ (конструкция «у меня есть»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">عِنْدَ مَعَ الضَّمِيرِ لِمَعْنَى الْمِلْكِ</span><p class="rule-study-text">конструкция «у меня есть». عِنْدِي قَلَمٌ. — У меня есть ручка. أَعِنْدَكَ سَيَّارَةٌ؟ — У тебя есть машина?</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">عِنْدَ مَعَ الضَّمِيرِ لِمَعْنَى الْمِلْكِ</span><span class="rule-term-ru">конструкция «у меня есть»</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">ضَمِيرٌ</span><span class="rule-term-ru">местоимение</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите лицо: говорящий, собеседник или отсутствующий.</li><li>Определите число и род.</li><li>Проверьте: местоимение самостоятельное или присоединённое к слову.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">عِنْدِي قَلَمٌ.</span><span class="rule-example-ru">У меня есть ручка.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">أَعِنْدَكَ سَيَّارَةٌ؟</span><span class="rule-example-ru">У тебя есть машина?</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>عِنْدِي قَلَمٌ.</b> — У меня есть ручка.</li><li><b>أَعِنْدَكَ سَيَّارَةٌ؟</b> — У тебя есть машина?</li></ul><br><br>Буквально это местная конструкция «при мне/при тебе находится…».</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте самостоятельные ضَمَائِرُ مُنْفَصِلَةٌ с присоединёнными ضَمَائِرُ مُتَّصِلَةٌ.</div></div>', 3, 'rule', 'Название и смысл عِنْدَ مَعَ الضَّمِيرِ لِمَعْنَى الْمِلْكِ конструкция «у меня есть». عِنْدِي قَلَمٌ. — У меня есть ручка. أَعِنْدَكَ سَيَّارَةٌ؟ — У тебя есть машина? Арабские слова → русский смысл عِنْدَ مَعَ الضَّمِيرِ لِمَعْنَى الْمِلْ'),
('Мединский курс (Том 1)', '10', 'لِـ مَعَ الضَّمَائِرِ (предлог لِـ с местоимениями)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">لِـ مَعَ الضَّمَائِرِ</span><p class="rule-study-text">предлог لِـ с местоимениями. Формы: لِي، لَكَ، لَهُ، لَهَا . لِي أَخٌ. — У меня есть брат. الْكِتَابُ لَهُ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لِـ مَعَ الضَّمَائِرِ</span><span class="rule-term-ru">предлог لِـ с местоимениями</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок отдельно.</li><li>Сравните русский смысл с примером.</li><li>Проверьте роль слов и их окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">لِي أَخٌ.</span><span class="rule-example-ru">У меня есть брат.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">الْكِتَابُ لَهُ.</span><span class="rule-example-ru">Книга принадлежит ему.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">Формы: <b>لِي، لَكَ، لَهُ، لَهَا</b>.<br><br><ul><li><b>لِي أَخٌ.</b> — У меня есть брат.</li><li><b>الْكِتَابُ لَهُ.</b> — Книга принадлежит ему.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не переводите правило отдельно от арабского примера: форма слова видна именно в предложении.</div></div>', 4, 'rule', 'Название и смысл لِـ مَعَ الضَّمَائِرِ предлог لِـ с местоимениями. Формы: لِي، لَكَ، لَهُ، لَهَا . لِي أَخٌ. — У меня есть брат. الْكِتَابُ لَهُ. Арабские слова → русский смысл لِـ مَعَ الضَّمَائِرِ предлог لِـ с местоимениями مَا что?: во'),
('Мединский курс (Том 1)', '10', 'ذَهَبْتَ وَذَهَبْتُ (прошедшее «ты пошёл» и «я пошёл»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">ذَهَبْتَ وَذَهَبْتُ</span><p class="rule-study-text">прошедшее «ты пошёл» и «я пошёл». أَيْنَ ذَهَبْتَ؟ ذَهَبْتُ إِلَى الْمَدْرَسَةِ. — Куда ты ходил? Я ходил в школу.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">ذَهَبْتَ وَذَهَبْتُ</span><span class="rule-term-ru">прошедшее «ты пошёл» и «я пошёл»</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الطَّالِبُ</span><span class="rule-term-ru">кто совершил действие</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">ذَهَبْتَ</span><span class="rule-term-ru">ты, мужчина</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَيْنَ</span><span class="rule-term-ru">где?: вопросительное имя места</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">حَرْفُ جَرٍّ</span><span class="rule-term-ru">предлог, после которого имя становится مَجْرُورٌ</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">حَرْفٌ</span><span class="rule-term-ru">частица / служебное слово</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمٌ</span><span class="rule-term-ru">имя: существительное, прилагательное, местоимение или другое именное слово</span></div><div class="rule-meaning-card rule-term-role"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">действующее лицо, подлежащее при глаголе</span></div><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">مَرْفُوعٌ</span><span class="rule-term-ru">в именительном падеже / в состоянии رفع</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">أَيْنَ ذَهَبْتَ؟ ذَهَبْتُ إِلَى الْمَدْرَسَةِ.</span><span class="rule-example-ru">Куда ты ходил? Я ходил в школу.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>أَيْنَ ذَهَبْتَ؟ ذَهَبْتُ إِلَى الْمَدْرَسَةِ.</b> — Куда ты ходил? Я ходил в школу.</li></ul><br><br><div class="iarab-example" dir="rtl"><br><br><span class="iarab-token role-fiil"><span class="iarab-word">ذَهَبَ</span><span class="iarab-label">فِعْلٌ مَاضٍ</span></span><br><br><span class="iarab-token role-fail"><span class="iarab-word">الطَّالِبُ</span><span class="iarab-label">فَاعِلٌ مَرْفُوعٌ</span></span><br><br><span class="iarab-token role-harf"><span class="iarab-word">إِلَى</span><span class="iarab-label">حَرْفُ جَرٍّ</span></span><br><br><span class="iarab-token role-majrur"><span class="iarab-word">الْمَدْرَسَةِ</span><span class="iarab-label">اِسْمٌ مَجْرُورٌ</span></span><br><br></div><br><br><b>ذَهَبَ الطَّالِبُ إِلَى الْمَدْرَسَةِ.</b> — Студент пошёл в школу. Глагол сообщает действие; <b>الطَّالِبُ</b> — кто совершил действие; после <b>إِلَى</b> слово получает родительный падеж.<br><br><b>ذَهَبْتَ</b> — ты, мужчина; <b>ذَهَبْتُ</b> — я. Окончание одновременно показывает лицо, поэтому отдельное местоимение обычно не требуется.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 5, 'rule', 'Название и смысл ذَهَبْتَ وَذَهَبْتُ прошедшее «ты пошёл» и «я пошёл». أَيْنَ ذَهَبْتَ؟ ذَهَبْتُ إِلَى الْمَدْرَسَةِ. — Куда ты ходил? Я ходил в школу. Арабские слова → русский смысл ذَهَبْتَ وَذَهَبْتُ прошедшее «ты пошёл» и «я пошёл» الطّ'),
('Мединский курс (Том 1)', '10', 'مَعَ وَعِنْدَ (различие «вместе с» и «у»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مَعَ وَعِنْدَ</span><p class="rule-study-text">различие «вместе с» и «у». مَعَ обозначает совместность без привязки к месту, عِنْدَ — нахождение у кого-либо или рядом с ним. الْمُدَرِّسُ مَعَ الْمُدِيرِ. — Учитель вместе с директором. الْمُدَرِّسُ عِنْدَ الْمُدِيرِ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَعَ وَعِنْدَ</span><span class="rule-term-ru">различие «вместе с» и «у»</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">عِنْدَ</span><span class="rule-term-ru">нахождение у кого-либо или рядом с ним</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок отдельно.</li><li>Сравните русский смысл с примером.</li><li>Проверьте роль слов и их окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">الْمُدَرِّسُ مَعَ الْمُدِيرِ.</span><span class="rule-example-ru">Учитель вместе с директором.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">الْمُدَرِّسُ عِنْدَ الْمُدِيرِ.</span><span class="rule-example-ru">Учитель у директора.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>مَعَ</b> обозначает совместность без привязки к месту, <b>عِنْدَ</b> — нахождение у кого-либо или рядом с ним.<br><br><ul><li><b>الْمُدَرِّسُ مَعَ الْمُدِيرِ.</b> — Учитель вместе с директором.</li><li><b>الْمُدَرِّسُ عِنْدَ الْمُدِيرِ.</b> — Учитель у директора.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не переводите правило отдельно от арабского примера: форма слова видна именно в предложении.</div></div>', 6, 'rule', 'Название и смысл مَعَ وَعِنْدَ различие «вместе с» и «у». مَعَ обозначает совместность без привязки к месту, عِنْدَ — нахождение у кого-либо или рядом с ним. الْمُدَرِّسُ مَعَ الْمُدِيرِ. — Учитель вместе с директором. الْمُدَرِّسُ عِنْدَ ا'),
('Мединский курс (Том 1)', '10', 'مَا النَّافِيَةُ (отрицательная مَا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مَا النَّافِيَةُ</span><p class="rule-study-text">отрицательная مَا. مَا عِنْدِي سَيَّارَةٌ. — У меня нет машины. Здесь مَا не означает «что?», а отрицает сообщение. Значение определяется контекстом и отсутствием вопросительной конструкции.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا النَّافِيَةُ</span><span class="rule-term-ru">отрицательная مَا</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَا عِنْدِي سَيَّارَةٌ.</span><span class="rule-example-ru">У меня нет машины.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>مَا عِنْدِي سَيَّارَةٌ.</b> — У меня нет машины.</li></ul><br><br>Здесь <b>مَا</b> не означает «что?», а отрицает сообщение. Значение определяется контекстом и отсутствием вопросительной конструкции.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 7, 'rule', 'Название и смысл مَا النَّافِيَةُ отрицательная مَا. مَا عِنْدِي سَيَّارَةٌ. — У меня нет машины. Здесь مَا не означает «что?», а отрицает сообщение. Значение определяется контекстом и отсутствием вопросительной конструкции. Арабские слова '),
('Мединский курс (Том 1)', '11', 'فِيهِ وَفِيهَا (предлог فِي с местоименными суффиксами)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">فِيهِ وَفِيهَا</span><p class="rule-study-text">предлог فِي с местоименными суффиксами. Автор прямо называет этот урок повторительным; новых конструкций мало. فِيهِ — в нём/там (для мужского рода), فِيهَا — в ней/там (для женского рода). مَنْ فِي الْبَيْتِ؟ فِيهِ أَبِي وَأُمِّي.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">فِيهِ وَفِيهَا</span><span class="rule-term-ru">предлог فِي с местоименными суффиксами</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">فِيهِ</span><span class="rule-term-ru">в нём/там (для мужского рода), فِيهَا — в ней/там (для женского рода)</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَنْ فِي الْبَيْتِ؟ فِيهِ أَبِي وَأُمِّي.</span><span class="rule-example-ru">Кто в доме? В нём мои отец и мать.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَنْ فِي الْغُرْفَةِ؟ فِيهَا أَخِي.</span><span class="rule-example-ru">Кто в комнате? В ней мой брат.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">Автор прямо называет этот урок повторительным; новых конструкций мало.<br><br><b>فِيهِ</b> — в нём/там (для мужского рода), <b>فِيهَا</b> — в ней/там (для женского рода).<br><br><ul><li><b>مَنْ فِي الْبَيْتِ؟ فِيهِ أَبِي وَأُمِّي.</b> — Кто в доме? В нём мои отец и мать.</li><li><b>مَنْ فِي الْغُرْفَةِ؟ فِيهَا أَخِي.</b> — Кто в комнате? В ней мой брат.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 1, 'rule', 'Название и смысл فِيهِ وَفِيهَا предлог فِي с местоименными суффиксами. Автор прямо называет этот урок повторительным; новых конструкций мало. فِيهِ — в нём/там (для мужского рода), فِيهَا — в ней/там (для женского рода). مَنْ فِي الْبَيْتِ'),
('Мединский курс (Том 1)', '11', 'الْمَفْعُولُ بِهِ (прямое дополнение)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمَفْعُولُ بِهِ</span><p class="rule-study-text">прямое дополнение. После переходного глагола объект ставится в винительном падеже مَنْصُوبٌ . أُحِبُّ اللَّهَ. — Я люблю Аллаха. أُحِبُّ الرَّسُولَ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-role"><span class="rule-term-ar" dir="rtl" lang="ar">الْمَفْعُولُ بِهِ</span><span class="rule-term-ru">прямое дополнение</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-role"><span class="rule-term-ar" dir="rtl" lang="ar">مَفْعُولٌ بِهِ</span><span class="rule-term-ru">прямое дополнение</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْصُوبٌ</span><span class="rule-term-ru">в винительном падеже / в состоянии نصب</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-role"><span class="rule-example-ar" dir="rtl" lang="ar">أُحِبُّ اللَّهَ.</span><span class="rule-example-ru">Я люблю Аллаха.</span></div><div class="rule-example-card rule-term-role"><span class="rule-example-ar" dir="rtl" lang="ar">أُحِبُّ الرَّسُولَ.</span><span class="rule-example-ru">Я люблю Посланника.</span></div><div class="rule-example-card rule-term-role"><span class="rule-example-ar" dir="rtl" lang="ar">أُحِبُّ اللُّغَةَ الْعَرَبِيَّةَ.</span><span class="rule-example-ru">Я люблю арабский язык.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">После переходного глагола объект ставится в винительном падеже <b>مَنْصُوبٌ</b>.<br><br><ul><li><b>أُحِبُّ اللَّهَ.</b> — Я люблю Аллаха.</li><li><b>أُحِبُّ الرَّسُولَ.</b> — Я люблю Посланника.</li><li><b>أُحِبُّ اللُّغَةَ الْعَرَبِيَّةَ.</b> — Я люблю арабский язык.</li></ul><br><br><b>Дополнительное объяснение.</b> В единственном числе обычным признаком винительного падежа является фатха, но не всякое дополнение во всех формах помечается именно фатхой. Правильно говорить: «дополнение стоит в винительном падеже», а не «всегда заканчивается на фатху».</div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 2, 'rule', 'Название и смысл الْمَفْعُولُ بِهِ прямое дополнение. После переходного глагола объект ставится в винительном падеже مَنْصُوبٌ . أُحِبُّ اللَّهَ. — Я люблю Аллаха. أُحِبُّ الرَّسُولَ. Арабские слова → русский смысл الْمَفْعُولُ بِهِ прямое '),
('Мединский курс (Том 1)', '11', 'أُحِبُّ وَتُحِبُّ، مَنْ؟ وَمَاذَا؟ (глаголы «люблю/любишь», вопросы к объекту)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أُحِبُّ وَتُحِبُّ، مَنْ؟ وَمَاذَا؟</span><p class="rule-study-text">глаголы «люблю/любишь», вопросы к объекту. أَتُحِبُّ لُغَتَكَ؟ — Ты любишь свой язык? مَنْ تُحِبُّ؟ — Кого ты любишь?</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">أُحِبُّ وَتُحِبُّ، مَنْ؟ وَمَاذَا؟</span><span class="rule-term-ru">глаголы «люблю/любишь», вопросы к объекту</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">أَتُحِبُّ لُغَتَكَ؟</span><span class="rule-example-ru">Ты любишь свой язык?</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">مَنْ تُحِبُّ؟</span><span class="rule-example-ru">Кого ты любишь?</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">مَاذَا تُحِبُّ؟</span><span class="rule-example-ru">Что ты любишь?</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>أَتُحِبُّ لُغَتَكَ؟</b> — Ты любишь свой язык?</li><li><b>مَنْ تُحِبُّ؟</b> — Кого ты любишь?</li><li><b>مَاذَا تُحِبُّ؟</b> — Что ты любишь?</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 3, 'rule', 'Название и смысл أُحِبُّ وَتُحِبُّ، مَنْ؟ وَمَاذَا؟ глаголы «люблю/любишь», вопросы к объекту. أَتُحِبُّ لُغَتَكَ؟ — Ты любишь свой язык? مَنْ تُحِبُّ؟ — Кого ты любишь? Арабские слова → русский смысл أُحِبُّ وَتُحِبُّ، مَنْ؟ وَمَاذَا؟ глаг'),
('Мединский курс (Том 1)', '11', 'الْمَعْطُوفُ بِالْوَاوِ (слово, присоединённое союзом وَ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمَعْطُوفُ بِالْوَاوِ</span><p class="rule-study-text">слово, присоединённое союзом وَ. الْمَعْطُوفُ — слово, присоединённое к предыдущему слову через союз وَ . Оно следует за тем словом в падеже. الْمُدَرِّسُ وَالْمُدِيرُ فِي الْفَصْلِ — Учитель и директор в классе. ذَهَبَ مُحَمَّدٌ إِلَى عَبَّاسٍ وَخَالِدٍ — Мухаммад пошёл к Аббасу и Халиду.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْمَعْطُوفُ بِالْوَاوِ</span><span class="rule-term-ru">слово, присоединённое союзом وَ</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْمَعْطُوفُ</span><span class="rule-term-ru">слово, присоединённое к предыдущему слову через союз وَ</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُدَرِّسُ وَالْمُدِيرُ فِي الْفَصْلِ</span><span class="rule-term-ru">Учитель и директор в классе</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">خَالِدٍ</span><span class="rule-term-ru">مَعْطُوفٌ عَلَى عَبَّاسٍ — Халид присоединён к Аббасу и поэтому тоже в جَرّ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">الْمُدَرِّسُ وَالْمُدِيرُ فِي الْفَصْلِ</span><span class="rule-example-ru">Учитель и директор в классе.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">ذَهَبَ مُحَمَّدٌ إِلَى عَبَّاسٍ وَخَالِدٍ</span><span class="rule-example-ru">Мухаммад пошёл к Аббасу и Халиду.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">خَالِدٍ: مَعْطُوفٌ عَلَى عَبَّاسٍ</span><span class="rule-example-ru">Халид присоединён к Аббасу и поэтому тоже в جَرّ.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><p><b>الْمَعْطُوفُ</b> — слово, присоединённое к предыдущему слову через союз <b>وَ</b>. Оно следует за тем словом в падеже.</p><ul><li>الْمُدَرِّسُ وَالْمُدِيرُ فِي الْفَصْلِ — Учитель и директор в классе.</li><li>ذَهَبَ مُحَمَّدٌ إِلَى عَبَّاسٍ وَخَالِدٍ — Мухаммад пошёл к Аббасу и Халиду.</li><li>خَالِدٍ: مَعْطُوفٌ عَلَى عَبَّاسٍ — Халид присоединён к Аббасу и поэтому тоже в جَرّ.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 4, 'rule', 'Название и смысл الْمَعْطُوفُ بِالْوَاوِ слово, присоединённое союзом وَ. الْمَعْطُوفُ — слово, присоединённое к предыдущему слову через союз وَ . Оно следует за тем словом в падеже. الْمُدَرِّسُ وَالْمُدِيرُ فِي الْفَصْلِ — Учитель и дирек'),
('Мединский курс (Том 1)', '12', 'أَنْتِ وَـكِ (женское «ты» и «твой»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَنْتِ وَـكِ</span><p class="rule-study-text">женское «ты» и «твой». أَنْتِ обращено к одной женщине; соответствующий притяжательный суффикс — ـكِ . مِنْ أَيْنَ أَنْتِ يَا آمِنَةُ؟ — Откуда ты, Амина? أَيْنَ بَيْتُكِ يَا مَرْيَمُ؟</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">أَنْتِ وَـكِ</span><span class="rule-term-ru">женское «ты» и «твой»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَيْنَ</span><span class="rule-term-ru">где?: вопросительное имя места</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">مِنْ أَيْنَ أَنْتِ يَا آمِنَةُ؟</span><span class="rule-example-ru">Откуда ты, Амина?</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">أَيْنَ بَيْتُكِ يَا مَرْيَمُ؟</span><span class="rule-example-ru">Где твой дом, Марьям?</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>أَنْتِ</b> обращено к одной женщине; соответствующий притяжательный суффикс — <b>ـكِ</b>.<br><br><ul><li><b>مِنْ أَيْنَ أَنْتِ يَا آمِنَةُ؟</b> — Откуда ты, Амина?</li><li><b>أَيْنَ بَيْتُكِ يَا مَرْيَمُ؟</b> — Где твой дом, Марьям?</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 1, 'rule', 'Название и смысл أَنْتِ وَـكِ женское «ты» и «твой». أَنْتِ обращено к одной женщине; соответствующий притяжательный суффикс — ـكِ . مِنْ أَيْنَ أَنْتِ يَا آمِنَةُ؟ — Откуда ты, Амина? أَيْنَ بَيْتُكِ يَا مَرْيَمُ؟ Арабские слова → русский '),
('Мединский курс (Том 1)', '12', 'ذَهَبَتْ (форма «она пошла»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">ذَهَبَتْ</span><p class="rule-study-text">форма «она пошла». ذَهَبَتْ آمِنَةُ إِلَى الْجَامِعَةِ. — Амина пошла в университет. Если подлежащее названо, هِيَ опускается. В форме ذَهَبَتْ конечная تْ имеет сукун.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">ذَهَبَتْ</span><span class="rule-term-ru">форма «она пошла»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">ذَهَبَتْ آمِنَةُ إِلَى الْجَامِعَةِ.</span><span class="rule-example-ru">Амина пошла в университет.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>ذَهَبَتْ آمِنَةُ إِلَى الْجَامِعَةِ.</b> — Амина пошла в университет.</li></ul><br><br>Если подлежащее названо, <b>هِيَ</b> опускается. В форме <b>ذَهَبَتْ</b> конечная <b>تْ</b> имеет сукун. Перед словом с соединительной хамзой для удобства произношения возникает касра: <b>ذَهَبَتِ الْبِنْتُ</b>.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 2, 'rule', 'Название и смысл ذَهَبَتْ форма «она пошла». ذَهَبَتْ آمِنَةُ إِلَى الْجَامِعَةِ. — Амина пошла в университет. Если подлежащее названо, هِيَ опускается. В форме ذَهَبَتْ конечная تْ имеет сукун. Арабские слова → русский смысл ذَهَبَتْ форма'),
('Мединский курс (Том 1)', '12', 'الِاسْمُ الْمَوْصُولُ: الَّتِي (относительное слово «которая»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الِاسْمُ الْمَوْصُولُ: الَّتِي</span><p class="rule-study-text">относительное слово «которая». الطَّالِبَةُ الَّتِي جَلَسَتْ أَمَامَ الْمُدَرِّسَةِ مِنْ أَلْمَانِيَا. — Студентка, которая сидела перед преподавательницей, из Германии.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الِاسْمُ الْمَوْصُولُ: الَّتِي</span><span class="rule-term-ru">относительное слово «которая»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمٌ</span><span class="rule-term-ru">имя: существительное, прилагательное, местоимение или другое именное слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">الطَّالِبَةُ الَّتِي جَلَسَتْ أَمَامَ الْمُدَرِّسَةِ مِنْ أَلْمَانِيَا.</span><span class="rule-example-ru">Студентка, которая сидела перед преподавательницей, из Германии.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>الطَّالِبَةُ الَّتِي جَلَسَتْ أَمَامَ الْمُدَرِّسَةِ مِنْ أَلْمَانِيَا.</b> — Студентка, которая сидела перед преподавательницей, из Германии.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 3, 'rule', 'Название и смысл الِاسْمُ الْمَوْصُولُ: الَّتِي относительное слово «которая». الطَّالِبَةُ الَّتِي جَلَسَتْ أَمَامَ الْمُدَرِّسَةِ مِنْ أَلْمَانِيَا. — Студентка, которая сидела перед преподавательницей, из Германии. Арабские слова → русск'),
('Мединский курс (Том 1)', '12', 'الضَّمِيرُ الْمُنْفَصِلُ لِلتَّوْكِيدِ (отдельное местоимение для подчёркивания)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الضَّمِيرُ الْمُنْفَصِلُ لِلتَّوْكِيدِ</span><p class="rule-study-text">отдельное местоимение для подчёркивания. هَذَا كِتَابُكَ أَنْتَ. — Это именно твоя книга. هَذَا بَيْتُهُ هُوَ. — Это именно его дом.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">الضَّمِيرُ الْمُنْفَصِلُ لِلتَّوْكِيدِ</span><span class="rule-term-ru">отдельное местоимение для подчёркивания</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">это / этот: указательное имя для близкого мужского рода</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ذَلِكَ</span><span class="rule-term-ru">то / тот: указательное имя для далёкого мужского рода</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">ضَمِيرٌ</span><span class="rule-term-ru">местоимение</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا كِتَابُكَ أَنْتَ.</span><span class="rule-example-ru">Это именно твоя книга.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا بَيْتُهُ هُوَ.</span><span class="rule-example-ru">Это именно его дом.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">ذَلِكَ كِتَابُهَا هِيَ.</span><span class="rule-example-ru">Та книга именно её.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>هَذَا كِتَابُكَ أَنْتَ.</b> — Это именно твоя книга.</li><li><b>هَذَا بَيْتُهُ هُوَ.</b> — Это именно его дом.</li><li><b>ذَلِكَ كِتَابُهَا هِيَ.</b> — Та книга именно её.</li></ul><br><br>Здесь конечное отдельное местоимение добавляет подчёркивание или снимает сомнение.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 4, 'rule', 'Название и смысл الضَّمِيرُ الْمُنْفَصِلُ لِلتَّوْكِيدِ отдельное местоимение для подчёркивания. هَذَا كِتَابُكَ أَنْتَ. — Это именно твоя книга. هَذَا بَيْتُهُ هُوَ. — Это именно его дом. Арабские слова → русский смысл الضَّمِيرُ الْمُنْفَ'),
('Мединский курс (Том 1)', '12', 'الْتِقَاءُ السَّاكِنَيْنِ (встреча двух сукунов)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْتِقَاءُ السَّاكِنَيْنِ</span><p class="rule-study-text">встреча двух сукунов. Если при чтении встречаются две буквы с сукуном подряд, арабская речь обычно устраняет трудность произношения: первая из двух неподвижных букв получает вспомогательную гласную. ذَهَبَتْ + الْمُدَرِّسَةُ → ذَهَبَتِ الْمُدَرِّسَةُ — Учительница ушла. مِنْ + الْبَيْتِ → مِنَ الْبَيْتِ — из дома. Важное исключение из объяснения учителя: предлог مِنْ перед أَلْـ получает фатху: مِنَ الْـ .</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الْتِقَاءُ السَّاكِنَيْنِ</span><span class="rule-term-ru">встреча двух сукунов</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">ذَهَبَتِ الْمُدَرِّسَةُ</span><span class="rule-term-ru">Учительница ушла</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مِنَ الْبَيْتِ</span><span class="rule-term-ru">из дома</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَلْـ</span><span class="rule-term-ru">определённый артикль</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">ذَهَبَتْ + الْمُدَرِّسَةُ → ذَهَبَتِ الْمُدَرِّسَةُ</span><span class="rule-example-ru">Учительница ушла.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مِنْ + الْبَيْتِ → مِنَ الْبَيْتِ</span><span class="rule-example-ru">из дома.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><p>Если при чтении встречаются две буквы с сукуном подряд, арабская речь обычно устраняет трудность произношения: первая из двух неподвижных букв получает вспомогательную гласную.</p><ul><li>ذَهَبَتْ + الْمُدَرِّسَةُ → ذَهَبَتِ الْمُدَرِّسَةُ — Учительница ушла.</li><li>مِنْ + الْبَيْتِ → مِنَ الْبَيْتِ — из дома.</li></ul><p>Важное исключение из объяснения учителя: предлог <b>مِنْ</b> перед <b>أَلْـ</b> получает фатху: <b>مِنَ الْـ</b>.</p></div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 5, 'rule', 'Название и смысл الْتِقَاءُ السَّاكِنَيْنِ встреча двух сукунов. Если при чтении встречаются две буквы с сукуном подряд, арабская речь обычно устраняет трудность произношения: первая из двух неподвижных букв получает вспомогательную гласную'),
('Мединский курс (Том 1)', '13', 'الْجَمْعُ السَّالِمُ وَجَمْعُ التَّكْسِيرِ (правильное и ломаное множественное число)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْجَمْعُ السَّالِمُ وَجَمْعُ التَّكْسِيرِ</span><p class="rule-study-text">правильное и ломаное множественное число. В правильном множественном основа сохраняется; в ломаном изменяется внутренняя структура слова. مُسْلِمٌ ← مُسْلِمُونَ — мусульманин → мусульмане. مُسْلِمَةٌ ← مُسْلِمَاتٌ — мусульманка → мусульманки. كِتَابٌ ← كُتُبٌ — книга → книги.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الْجَمْعُ السَّالِمُ وَجَمْعُ التَّكْسِيرِ</span><span class="rule-term-ru">правильное и ломаное множественное число</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مُسْلِمُونَ</span><span class="rule-term-ru">мусульманин → мусульмане</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مُسْلِمَاتٌ</span><span class="rule-term-ru">мусульманка → мусульманки</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">كُتُبٌ</span><span class="rule-term-ru">книга → книги</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">رِجَالٌ</span><span class="rule-term-ru">мужчина → мужчины</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок отдельно.</li><li>Сравните русский смысл с примером.</li><li>Проверьте роль слов и их окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">مُسْلِمٌ ← مُسْلِمُونَ</span><span class="rule-example-ru">мусульманин → мусульмане.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">مُسْلِمَةٌ ← مُسْلِمَاتٌ</span><span class="rule-example-ru">мусульманка → мусульманки.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">كِتَابٌ ← كُتُبٌ</span><span class="rule-example-ru">книга → книги.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">رَجُلٌ ← رِجَالٌ</span><span class="rule-example-ru">мужчина → мужчины.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">В правильном множественном основа сохраняется; в ломаном изменяется внутренняя структура слова.<br><br><ul><li><b>مُسْلِمٌ ← مُسْلِمُونَ</b> — мусульманин → мусульмане.</li><li><b>مُسْلِمَةٌ ← مُسْلِمَاتٌ</b> — мусульманка → мусульманки.</li><li><b>كِتَابٌ ← كُتُبٌ</b> — книга → книги.</li><li><b>رَجُلٌ ← رِجَالٌ</b> — мужчина → мужчины.</li></ul><br><br>В этом уроке мужское правильное множественное вводится в именительной форме <b>ـُونَ</b>. Женское правильное множественное: заменить <b>ة</b> на <b>اتٌ</b>.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не переводите правило отдельно от арабского примера: форма слова видна именно в предложении.</div></div>', 1, 'rule', 'Название и смысл الْجَمْعُ السَّالِمُ وَجَمْعُ التَّكْسِيرِ правильное и ломаное множественное число. В правильном множественном основа сохраняется; в ломаном изменяется внутренняя структура слова. مُسْلِمٌ ← مُسْلِمُونَ — мусульманин → мус'),
('Мединский курс (Том 1)', '13', 'الْمُبْتَدَأُ (первый член именного предложения)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمُبْتَدَأُ</span><p class="rule-study-text">первый член именного предложения. Суть правила. الْمُبْتَدَأُ — слово, о котором сообщается в именном предложении. В упражнениях этого урока оно изменяется из единственного числа во множественное. هَذَا طَالِبٌ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُبْتَدَأُ</span><span class="rule-term-ru">первый член именного предложения</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">это / этот: указательное имя для близкого мужского рода</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَؤُلَاءِ</span><span class="rule-term-ru">эти: указательное имя для множественного разумных</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">مُبْتَدَأٌ</span><span class="rule-term-ru">подлежащее именного предложения</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите مُبْتَدَأٌ: о ком или о чём говорится.</li><li>Найдите خَبَرٌ: что сообщается.</li><li>Оба главных члена обычно مَرْفُوعٌ.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا طَالِبٌ. → هَؤُلَاءِ طُلَّابٌ.</span><span class="rule-example-ru">Это студент. → Это студенты. Меняется мубтада; форма сообщения также согласуется с ним.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>Суть правила.</b> <b>الْمُبْتَدَأُ</b> — слово, о котором сообщается в именном предложении. В упражнениях этого урока оно изменяется из единственного числа во множественное.<br><br><ul><li><b>هَذَا طَالِبٌ. → هَؤُلَاءِ طُلَّابٌ.</b> — Это студент. → Это студенты. Меняется мубтада; форма сообщения также согласуется с ним.</li></ul><br><br><b>Дополнительное объяснение.</b> В простом именном предложении мубтада обычно стоит в начале и имеет именительный падеж. На этом этапе достаточно узнавать его как главный предмет сообщения; термин «хабар» будет введён в уроке 17.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не называйте любое первое слово مُبْتَدَأٌ автоматически: сначала проверьте, даёт ли второе слово законченное сообщение.</div></div>', 2, 'rule', 'Название и смысл الْمُبْتَدَأُ первый член именного предложения. Суть правила. الْمُبْتَدَأُ — слово, о котором сообщается в именном предложении. В упражнениях этого урока оно изменяется из единственного числа во множественное. هَذَا طَالِب'),
('Мединский курс (Том 1)', '13', 'هَؤُلَاءِ (указательное слово «эти» для людей)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">هَؤُلَاءِ</span><p class="rule-study-text">указательное слово «эти» для людей. هَؤُلَاءِ употребляется для близкой группы людей обоих родов. هَؤُلَاءِ طُلَّابٌ. — Эти люди — студенты. هَؤُلَاءِ مُدَرِّسَاتٌ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَؤُلَاءِ</span><span class="rule-term-ru">указательное слово «эти» для людей</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">هَؤُلَاءِ طُلَّابٌ.</span><span class="rule-example-ru">Эти люди — студенты.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">هَؤُلَاءِ مُدَرِّسَاتٌ.</span><span class="rule-example-ru">Эти женщины — преподавательницы.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>هَؤُلَاءِ</b> употребляется для близкой группы людей обоих родов.<br><br><ul><li><b>هَؤُلَاءِ طُلَّابٌ.</b> — Эти люди — студенты.</li><li><b>هَؤُلَاءِ مُدَرِّسَاتٌ.</b> — Эти женщины — преподавательницы.</li></ul><br><br>В рамках первого тома не следует преждевременно применять <b>هَؤُلَاءِ</b> к обычным неодушевлённым множественным: их согласование вводится в уроке 16.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 3, 'rule', 'Название и смысл هَؤُلَاءِ указательное слово «эти» для людей. هَؤُلَاءِ употребляется для близкой группы людей обоих родов. هَؤُلَاءِ طُلَّابٌ. — Эти люди — студенты. هَؤُلَاءِ مُدَرِّسَاتٌ. Арабские слова → русский смысл هَؤُلَاءِ указате'),
('Мединский курс (Том 1)', '13', 'هُمْ، هُنَّ وَضَمَائِرُ الْمِلْكِ (местоимения «они/их»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">هُمْ، هُنَّ وَضَمَائِرُ الْمِلْكِ</span><p class="rule-study-text">местоимения «они/их». هُمْ — они, мужчины или смешанная группа; هُنَّ — они, женщины. Эти же формы после существительного функционируют как суффиксы ـهُمْ، ـهُنَّ со значением «их». هُمْ إِخْوَتِي. — Они мои братья.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">هُمْ، هُنَّ وَضَمَائِرُ الْمِلْكِ</span><span class="rule-term-ru">местоимения «они/их»</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">هُمْ</span><span class="rule-term-ru">они, мужчины или смешанная группа</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">هُنَّ</span><span class="rule-term-ru">они, женщины</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">это / этот: указательное имя для близкого мужского рода</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">هُمْ إِخْوَتِي.</span><span class="rule-example-ru">Они мои братья.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">هُنَّ أَخَوَاتِي.</span><span class="rule-example-ru">Они мои сёстры.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَا بَيْتُهُمْ.</span><span class="rule-example-ru">Это их дом.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>هُمْ</b> — они, мужчины или смешанная группа; <b>هُنَّ</b> — они, женщины. Эти же формы после существительного функционируют как суффиксы <b>ـهُمْ، ـهُنَّ</b> со значением «их».<br><br><ul><li><b>هُمْ إِخْوَتِي.</b> — Они мои братья.</li><li><b>هُنَّ أَخَوَاتِي.</b> — Они мои сёстры.</li><li><b>هَذَا بَيْتُهُمْ.</b> — Это их дом.</li></ul><br><br>В базе нельзя переводить самостоятельное <b>هُمْ</b> просто как «их».</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 4, 'rule', 'Название и смысл هُمْ، هُنَّ وَضَمَائِرُ الْمِلْكِ местоимения «они/их». هُمْ — они, мужчины или смешанная группа; هُنَّ — они, женщины. Эти же формы после существительного функционируют как суффиксы ـهُمْ، ـهُنَّ со значением «их». هُمْ إِ'),
('Мединский курс (Том 1)', '13', 'ذَهَبُوا وَذَهَبْنَ (прошедшее время, «они пошли»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">ذَهَبُوا وَذَهَبْنَ</span><p class="rule-study-text">прошедшее время, «они пошли». ذَهَبُوا إِلَى الْجَامِعَةِ. — Они, мужчины, пошли в университет. ذَهَبْنَ إِلَى الْمَكْتَبَةِ. — Они, женщины, пошли в библиотеку.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">ذَهَبُوا وَذَهَبْنَ</span><span class="rule-term-ru">прошедшее время, «они пошли»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">ذَهَبُوا إِلَى الْجَامِعَةِ.</span><span class="rule-example-ru">Они, мужчины, пошли в университет.</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">ذَهَبْنَ إِلَى الْمَكْتَبَةِ.</span><span class="rule-example-ru">Они, женщины, пошли в библиотеку.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>ذَهَبُوا إِلَى الْجَامِعَةِ.</b> — Они, мужчины, пошли в университет.</li><li><b>ذَهَبْنَ إِلَى الْمَكْتَبَةِ.</b> — Они, женщины, пошли в библиотеку.</li></ul><br><br>В <b>ذَهَبُوا</b> конечная алиф не произносится; это орфографическая <b>أَلِفُ الْفَارِقَةِ</b> после <b>وَاوُ الْجَمَاعَةِ</b>.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 5, 'rule', 'Название и смысл ذَهَبُوا وَذَهَبْنَ прошедшее время, «они пошли». ذَهَبُوا إِلَى الْجَامِعَةِ. — Они, мужчины, пошли в университет. ذَهَبْنَ إِلَى الْمَكْتَبَةِ. — Они, женщины, пошли в библиотеку. Арабские слова → русский смысл ذَهَبُوا و'),
('Мединский курс (Том 1)', '13', 'بَعْضُهُمْ (конструкция «некоторые из них»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">بَعْضُهُمْ</span><p class="rule-study-text">конструкция «некоторые из них». بَعْضُهُمْ مُدَرِّسُونَ وَبَعْضُهُمْ مُهَنْدِسُونَ. — Некоторые из них учителя, а некоторые инженеры.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">بَعْضُهُمْ</span><span class="rule-term-ru">конструкция «некоторые из них»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите лицо: говорящий, собеседник или отсутствующий.</li><li>Определите число и род.</li><li>Проверьте: местоимение самостоятельное или присоединённое к слову.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">بَعْضُهُمْ مُدَرِّسُونَ وَبَعْضُهُمْ مُهَنْدِسُونَ.</span><span class="rule-example-ru">Некоторые из них учителя, а некоторые инженеры.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>بَعْضُهُمْ مُدَرِّسُونَ وَبَعْضُهُمْ مُهَنْدِسُونَ.</b> — Некоторые из них учителя, а некоторые инженеры.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте самостоятельные ضَمَائِرُ مُنْفَصِلَةٌ с присоединёнными ضَمَائِرُ مُتَّصِلَةٌ.</div></div>', 6, 'rule', 'Название и смысл بَعْضُهُمْ конструкция «некоторые из них». بَعْضُهُمْ مُدَرِّسُونَ وَبَعْضُهُمْ مُهَنْدِسُونَ. — Некоторые из них учителя, а некоторые инженеры. Арабские слова → русский смысл بَعْضُهُمْ конструкция «некоторые из них» وَ и '),
('Мединский курс (Том 1)', '13', 'أُولَئِكَ (указательное слово «те» во множественном числе)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أُولَئِكَ</span><p class="rule-study-text">указательное слово «те» во множественном числе. أُولَئِكَ — «те» для людей мужского и женского рода. Буква و в написании не произносится. أُولَئِكَ طُلَّابٌ. — Те люди — студенты.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أُولَئِكَ</span><span class="rule-term-ru">указательное слово «те» во множественном числе</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أُولَئِكَ طُلَّابٌ.</span><span class="rule-example-ru">Те люди — студенты.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أُولَئِكَ مُدَرِّسَاتٌ.</span><span class="rule-example-ru">Те женщины — преподавательницы.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>أُولَئِكَ</b> — «те» для людей мужского и женского рода. Буква <b>و</b> в написании не произносится.<br><br><ul><li><b>أُولَئِكَ طُلَّابٌ.</b> — Те люди — студенты.</li><li><b>أُولَئِكَ مُدَرِّسَاتٌ.</b> — Те женщины — преподавательницы.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 7, 'rule', 'Название и смысл أُولَئِكَ указательное слово «те» во множественном числе. أُولَئِكَ — «те» для людей мужского и женского рода. Буква و в написании не произносится. أُولَئِكَ طُلَّابٌ. — Те люди — студенты. Арабские слова → русский смысл أُ'),
('Мединский курс (Том 1)', '14', 'أَنْتُمْ وَـكُمْ (множественное «вы/ваш» к мужчинам или смешанной группе)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَنْتُمْ وَـكُمْ</span><p class="rule-study-text">множественное «вы/ваш» к мужчинам или смешанной группе. مَنْ أَنْتُمْ؟ — Кто вы? أَيْنَ بَيْتُكُمْ يَا إِخْوَانُ؟ — Где ваш дом, братья?</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">أَنْتُمْ وَـكُمْ</span><span class="rule-term-ru">множественное «вы/ваш» к мужчинам или смешанной группе</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَيْنَ</span><span class="rule-term-ru">где?: вопросительное имя места</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">كَمْ</span><span class="rule-term-ru">сколько?: вопросительное имя числа</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число.</li><li>Проверьте род единственного числа الْمَعْدُودُ.</li><li>После كَمْ ставьте تَمْيِيزٌ в نَصْب, а после 3-10 - множественное в جَرّ.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">مَنْ أَنْتُمْ؟</span><span class="rule-example-ru">Кто вы?</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">أَيْنَ بَيْتُكُمْ يَا إِخْوَانُ؟</span><span class="rule-example-ru">Где ваш дом, братья?</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>مَنْ أَنْتُمْ؟</b> — Кто вы?</li><li><b>أَيْنَ بَيْتُكُمْ يَا إِخْوَانُ؟</b> — Где ваш дом, братья?</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Для чисел 3-10 род числительного противоположен роду единственного числа считаемого слова.</div></div>', 1, 'rule', 'Название и смысл أَنْتُمْ وَـكُمْ множественное «вы/ваш» к мужчинам или смешанной группе. مَنْ أَنْتُمْ؟ — Кто вы? أَيْنَ بَيْتُكُمْ يَا إِخْوَانُ؟ — Где ваш дом, братья? Арабские слова → русский смысл أَنْتُمْ وَـكُمْ множественное «вы/ваш'),
('Мединский курс (Том 1)', '14', 'نَحْنُ وَـنَا (местоимения «мы/наш»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">نَحْنُ وَـنَا</span><p class="rule-study-text">местоимения «мы/наш». نَحْنُ и суффикс ـنَا употребляются для людей любого пола. نَحْنُ مُسْلِمُونَ. — Мы мусульмане. نَحْنُ مُسْلِمَاتٌ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">نَحْنُ وَـنَا</span><span class="rule-term-ru">местоимения «мы/наш»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите лицо: говорящий, собеседник или отсутствующий.</li><li>Определите число и род.</li><li>Проверьте: местоимение самостоятельное или присоединённое к слову.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">نَحْنُ مُسْلِمُونَ.</span><span class="rule-example-ru">Мы мусульмане.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">نَحْنُ مُسْلِمَاتٌ.</span><span class="rule-example-ru">Мы мусульманки.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">اللَّهُ رَبُّنَا.</span><span class="rule-example-ru">Аллах — наш Господь.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>نَحْنُ</b> и суффикс <b>ـنَا</b> употребляются для людей любого пола.<br><br><ul><li><b>نَحْنُ مُسْلِمُونَ.</b> — Мы мусульмане.</li><li><b>نَحْنُ مُسْلِمَاتٌ.</b> — Мы мусульманки.</li><li><b>اللَّهُ رَبُّنَا.</b> — Аллах — наш Господь.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте самостоятельные ضَمَائِرُ مُنْفَصِلَةٌ с присоединёнными ضَمَائِرُ مُتَّصِلَةٌ.</div></div>', 2, 'rule', 'Название и смысл نَحْنُ وَـنَا местоимения «мы/наш». نَحْنُ и суффикс ـنَا употребляются для людей любого пола. نَحْنُ مُسْلِمُونَ. — Мы мусульмане. نَحْنُ مُسْلِمَاتٌ. Арабские слова → русский смысл نَحْنُ وَـنَا местоимения «мы/наш» مَا ч'),
('Мединский курс (Том 1)', '14', 'ذَهَبْتُمْ وَذَهَبْنَا (прошедшее «вы пошли» и «мы пошли»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">ذَهَبْتُمْ وَذَهَبْنَا</span><p class="rule-study-text">прошедшее «вы пошли» и «мы пошли». أَيْنَ ذَهَبْتُمْ يَا أَبْنَائِي؟ — Куда вы пошли, мои сыновья? ذَهَبْنَا إِلَى الْمَسْجِدِ. — Мы пошли в мечеть.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">ذَهَبْتُمْ وَذَهَبْنَا</span><span class="rule-term-ru">прошедшее «вы пошли» и «мы пошли»</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">ذَهَبْنَا</span><span class="rule-term-ru">«мы пошли» и ذَهَبْنَ — «они, женщины, пошли»: долгота ـنَا различает формы</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَيْنَ</span><span class="rule-term-ru">где?: вопросительное имя места</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">أَيْنَ ذَهَبْتُمْ يَا أَبْنَائِي؟</span><span class="rule-example-ru">Куда вы пошли, мои сыновья?</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">ذَهَبْنَا إِلَى الْمَسْجِدِ.</span><span class="rule-example-ru">Мы пошли в мечеть.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>أَيْنَ ذَهَبْتُمْ يَا أَبْنَائِي؟</b> — Куда вы пошли, мои сыновья?</li><li><b>ذَهَبْنَا إِلَى الْمَسْجِدِ.</b> — Мы пошли в мечеть.</li></ul><br><br>Не путать <b>ذَهَبْنَا</b> — «мы пошли» и <b>ذَهَبْنَ</b> — «они, женщины, пошли»: долгота <b>ـنَا</b> различает формы.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 3, 'rule', 'Название и смысл ذَهَبْتُمْ وَذَهَبْنَا прошедшее «вы пошли» и «мы пошли». أَيْنَ ذَهَبْتُمْ يَا أَبْنَائِي؟ — Куда вы пошли, мои сыновья? ذَهَبْنَا إِلَى الْمَسْجِدِ. — Мы пошли в мечеть. Арабские слова → русский смысл ذَهَبْتُمْ وَذَهَبْن'),
('Мединский курс (Том 1)', '14', 'الْعَلَمُ الْأَعْجَمِيُّ الْمَمْنُوعُ مِنَ الصَّرْفِ (иноязычные имена без танвина)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْعَلَمُ الْأَعْجَمِيُّ الْمَمْنُوعُ مِنَ الصَّرْفِ</span><p class="rule-study-text">иноязычные имена без танвина. Большинство иноязычных собственных имён не принимает танвин: إِبْرَاهِيمُ، إِسْمَاعِيلُ، إِسْحَاقُ، لَنْدَنُ . Мужское трёхбуквенное имя с серединной неподвижной буквой может принимать танвин: نُوحٌ، لُوطٌ .</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْعَلَمُ الْأَعْجَمِيُّ الْمَمْنُوعُ مِنَ الصَّرْفِ</span><span class="rule-term-ru">иноязычные имена без танвина</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">إِبْرَاهِيمُ، إِسْمَاعِيلُ، إِسْحَاقُ، لَنْدَنُ</span><span class="rule-term-ru">примеры иноязычных имён/названий, которые не принимают танвин</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">اِسْمٌ</span><span class="rule-term-ru">имя: существительное, прилагательное, местоимение или другое именное слово</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْمَمْنُوعُ مِنَ الصَّرْفِ</span><span class="rule-term-ru">диптот: слово без танвина, с особым جَرّ</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَمْنُوعٌ مِنَ الصَّرْفِ</span><span class="rule-term-ru">диптот: слово без танвина, с особым جَرّ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Проверьте, относится ли слово к группе الْمَمْنُوعُ مِنَ الصَّرْفِ.</li><li>Не ставьте танвин.</li><li>В جَرّ без أَلْـ и без идафы ставьте фатху вместо касры.</li></ol></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">Большинство иноязычных собственных имён не принимает танвин: <b>إِبْرَاهِيمُ، إِسْمَاعِيلُ، إِسْحَاقُ، لَنْدَنُ</b>. Мужское трёхбуквенное имя с серединной неподвижной буквой может принимать танвин: <b>نُوحٌ، لُوطٌ</b>.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Диптот не «полностью неизменяемый»: он меняет падеж, но без танвина и с особым родительным падежом.</div></div>', 4, 'rule', 'Название и смысл الْعَلَمُ الْأَعْجَمِيُّ الْمَمْنُوعُ مِنَ الصَّرْفِ иноязычные имена без танвина. Большинство иноязычных собственных имён не принимает танвин: إِبْرَاهِيمُ، إِسْمَاعِيلُ، إِسْحَاقُ، لَنْدَنُ . Мужское трёхбуквенное имя с с'),
('Мединский курс (Том 1)', '14', 'نَعْتُ الْمُضَافِ الْمَعْرِفَةِ (прилагательное при определённом первом члене идафы)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">نَعْتُ الْمُضَافِ الْمَعْرِفَةِ</span><p class="rule-study-text">прилагательное при определённом первом члене идафы. بَيْتُ الْإِمَامِ الْجَدِيدُ. — Новый дом имама; الْجَدِيدُ описывает بَيْتُ . بَيْتُ الْإِمَامِ الْجَدِيدِ. — Дом нового имама; الْجَدِيدِ описывает الْإِمَامِ .</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">نَعْتُ الْمُضَافِ الْمَعْرِفَةِ</span><span class="rule-term-ru">прилагательное при определённом первом члене идафы</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مُضَافٌ</span><span class="rule-term-ru">первый член идафы</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">نَعْتٌ</span><span class="rule-term-ru">прилагательное / определение</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْمَعْرِفَةُ</span><span class="rule-term-ru">определённое / известное имя</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите مَنْعُوتٌ - определяемое слово.</li><li>После него поставьте نَعْتٌ.</li><li>Согласуйте نَعْتٌ с مَنْعُوتٌ в роде, числе, падеже и определённости.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">بَيْتُ الْإِمَامِ الْجَدِيدُ.</span><span class="rule-example-ru">Новый дом имама; الْجَدِيدُ описывает بَيْتُ .</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">بَيْتُ الْإِمَامِ الْجَدِيدِ.</span><span class="rule-example-ru">Дом нового имама; الْجَدِيدِ описывает الْإِمَامِ .</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>بَيْتُ الْإِمَامِ الْجَدِيدُ.</b> — Новый дом имама; <b>الْجَدِيدُ</b> описывает <b>بَيْتُ</b>.</li><li><b>بَيْتُ الْإِمَامِ الْجَدِيدِ.</b> — Дом нового имама; <b>الْجَدِيدِ</b> описывает <b>الْإِمَامِ</b>.</li></ul><br><br>Падеж помогает понять, к какому слову относится прилагательное.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Если существительное определённое, прилагательное тоже должно быть определённым; если оно после предлога, прилагательное тоже в جَرّ.</div></div>', 5, 'rule', 'Название и смысл نَعْتُ الْمُضَافِ الْمَعْرِفَةِ прилагательное при определённом первом члене идафы. بَيْتُ الْإِمَامِ الْجَدِيدُ. — Новый дом имама; الْجَدِيدُ описывает بَيْتُ . بَيْتُ الْإِمَامِ الْجَدِيدِ. — Дом нового имама; الْجَدِيدِ'),
('Мединский курс (Том 1)', '14', 'أَيُّ (вопросительное «какой/который»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَيُّ</span><p class="rule-study-text">вопросительное «какой/который». أَيُّ всегда является первым членом идафы, поэтому следующее существительное — в родительном падеже. Форма أَيُّ меняется по падежу. أَيُّ بَيْتٍ هَذَا؟ — Какой это дом?</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَيُّ</span><span class="rule-term-ru">вопросительное «какой/который»</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">это / этот: указательное имя для близкого мужского рода</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أَيُّ بَيْتٍ هَذَا؟</span><span class="rule-example-ru">Какой это дом?</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">أَيُّ طَالِبٍ خَرَجَ؟</span><span class="rule-example-ru">Который студент вышел?</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">مِنْ أَيِّ بَلَدٍ أَنْتَ؟</span><span class="rule-example-ru">Из какой ты страны?</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">فِي أَيِّ فَصْلٍ جَلَسْتَ؟</span><span class="rule-example-ru">В каком классе ты сидел?</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>أَيُّ</b> всегда является первым членом идафы, поэтому следующее существительное — в родительном падеже. Форма <b>أَيُّ</b> меняется по падежу.<br><br><ul><li><b>أَيُّ بَيْتٍ هَذَا؟</b> — Какой это дом?</li><li><b>أَيُّ طَالِبٍ خَرَجَ؟</b> — Который студент вышел?</li><li><b>مِنْ أَيِّ بَلَدٍ أَنْتَ؟</b> — Из какой ты страны?</li><li><b>فِي أَيِّ فَصْلٍ جَلَسْتَ؟</b> — В каком классе ты сидел?</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 6, 'rule', 'Название и смысл أَيُّ вопросительное «какой/который». أَيُّ всегда является первым членом идафы, поэтому следующее существительное — в родительном падеже. Форма أَيُّ меняется по падежу. أَيُّ بَيْتٍ هَذَا؟ — Какой это дом? Арабские слова '),
('Мединский курс (Том 1)', '15', 'أَنْتُنَّ وَـكُنَّ (женское множественное «вы/ваш»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَنْتُنَّ وَـكُنَّ</span><p class="rule-study-text">женское множественное «вы/ваш». مَنْ أَنْتُنَّ يَا أَخَوَاتِي؟ — Кто вы, мои сёстры? أَيْنَ بَيْتُكُنَّ يَا سَيِّدَاتُ؟ — Где ваш дом, дамы?</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">أَنْتُنَّ وَـكُنَّ</span><span class="rule-term-ru">женское множественное «вы/ваш»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَيْنَ</span><span class="rule-term-ru">где?: вопросительное имя места</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">مَنْ أَنْتُنَّ يَا أَخَوَاتِي؟</span><span class="rule-example-ru">Кто вы, мои сёстры?</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">أَيْنَ بَيْتُكُنَّ يَا سَيِّدَاتُ؟</span><span class="rule-example-ru">Где ваш дом, дамы?</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>مَنْ أَنْتُنَّ يَا أَخَوَاتِي؟</b> — Кто вы, мои сёстры?</li><li><b>أَيْنَ بَيْتُكُنَّ يَا سَيِّدَاتُ؟</b> — Где ваш дом, дамы?</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 1, 'rule', 'Название и смысл أَنْتُنَّ وَـكُنَّ женское множественное «вы/ваш». مَنْ أَنْتُنَّ يَا أَخَوَاتِي؟ — Кто вы, мои сёстры? أَيْنَ بَيْتُكُنَّ يَا سَيِّدَاتُ؟ — Где ваш дом, дамы? Арабские слова → русский смысл أَنْتُنَّ وَـكُنَّ женское множе'),
('Мединский курс (Том 1)', '15', 'ذَهَبْتُنَّ (форма «вы, женщины, пошли»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">ذَهَبْتُنَّ</span><p class="rule-study-text">форма «вы, женщины, пошли». أَيْنَ ذَهَبْتُنَّ يَا أَخَوَاتُ؟ — Куда вы пошли, сёстры? Сравните: ذَهَبْتُمْ — вы, мужчины/смешанная группа; ذَهَبْتُنَّ — вы, женщины.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">ذَهَبْتُنَّ</span><span class="rule-term-ru">форма «вы, женщины, пошли»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَيْنَ</span><span class="rule-term-ru">где?: вопросительное имя места</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок отдельно.</li><li>Сравните русский смысл с примером.</li><li>Проверьте роль слов и их окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">أَيْنَ ذَهَبْتُنَّ يَا أَخَوَاتُ؟</span><span class="rule-example-ru">Куда вы пошли, сёстры?</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>أَيْنَ ذَهَبْتُنَّ يَا أَخَوَاتُ؟</b> — Куда вы пошли, сёстры?</li></ul><br><br>Сравните: <b>ذَهَبْتُمْ</b> — вы, мужчины/смешанная группа; <b>ذَهَبْتُنَّ</b> — вы, женщины.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не переводите правило отдельно от арабского примера: форма слова видна именно в предложении.</div></div>', 2, 'rule', 'Название и смысл ذَهَبْتُنَّ форма «вы, женщины, пошли». أَيْنَ ذَهَبْتُنَّ يَا أَخَوَاتُ؟ — Куда вы пошли, сёстры? Сравните: ذَهَبْتُمْ — вы, мужчины/смешанная группа; ذَهَبْتُنَّ — вы, женщины. Арабские слова → русский смысл ذَهَبْتُنَّ ф'),
('Мединский курс (Том 1)', '15', 'قَبْلَ وَبَعْدَ (слова «до» и «после»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">قَبْلَ وَبَعْدَ</span><p class="rule-study-text">слова «до» и «после». В модели урока они являются первым членом идафы; следующее слово ставится в родительном падеже. بَعْدَ الدَّرْسِ — после урока. قَبْلَ الصَّلَاةِ — до молитвы.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">قَبْلَ وَبَعْدَ</span><span class="rule-term-ru">слова «до» и «после»</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">بَعْدَ الدَّرْسِ</span><span class="rule-term-ru">после урока</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">قَبْلَ الصَّلَاةِ</span><span class="rule-term-ru">до молитвы</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Прочитайте арабский заголовок отдельно.</li><li>Сравните русский смысл с примером.</li><li>Проверьте роль слов и их окончание.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">بَعْدَ الدَّرْسِ</span><span class="rule-example-ru">после урока.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">قَبْلَ الصَّلَاةِ</span><span class="rule-example-ru">до молитвы.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">В модели урока они являются первым членом идафы; следующее слово ставится в родительном падеже.<br><br><ul><li><b>بَعْدَ الدَّرْسِ</b> — после урока.</li><li><b>قَبْلَ الصَّلَاةِ</b> — до молитвы.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не переводите правило отдельно от арабского примера: форма слова видна именно в предложении.</div></div>', 3, 'rule', 'Название и смысл قَبْلَ وَبَعْدَ слова «до» и «после». В модели урока они являются первым членом идафы; следующее слово ставится в родительном падеже. بَعْدَ الدَّرْسِ — после урока. قَبْلَ الصَّلَاةِ — до молитвы. Арабские слова → русский '),
('Мединский курс (Том 1)', '15', 'رَجَعَ (глагол «вернулся»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">رَجَعَ</span><p class="rule-study-text">глагол «вернулся». أَرَجَعَ الْإِمَامُ مِنَ الْمَسْجِدِ؟ — Имам вернулся из мечети? ذَهَبْتُ إِلَى الْمَسْجِدِ قَبْلَ الْأَذَانِ وَرَجَعْتُ بَعْدَ الصَّلَاةِ. — Я пошёл в мечеть до азана и вернулся после молитвы.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">رَجَعَ</span><span class="rule-term-ru">глагол «вернулся»</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">أَرَجَعَ الْإِمَامُ مِنَ الْمَسْجِدِ؟</span><span class="rule-example-ru">Имам вернулся из мечети?</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">ذَهَبْتُ إِلَى الْمَسْجِدِ قَبْلَ الْأَذَانِ وَرَجَعْتُ بَعْدَ الصَّلَاةِ.</span><span class="rule-example-ru">Я пошёл в мечеть до азана и вернулся после молитвы.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>أَرَجَعَ الْإِمَامُ مِنَ الْمَسْجِدِ؟</b> — Имам вернулся из мечети?</li><li><b>ذَهَبْتُ إِلَى الْمَسْجِدِ قَبْلَ الْأَذَانِ وَرَجَعْتُ بَعْدَ الصَّلَاةِ.</b> — Я пошёл в мечеть до азана и вернулся после молитвы.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 4, 'rule', 'Название и смысл رَجَعَ глагол «вернулся». أَرَجَعَ الْإِمَامُ مِنَ الْمَسْجِدِ؟ — Имам вернулся из мечети? ذَهَبْتُ إِلَى الْمَسْجِدِ قَبْلَ الْأَذَانِ وَرَجَعْتُ بَعْدَ الصَّلَاةِ. — Я пошёл в мечеть до азана и вернулся после молитвы. Ара'),
('Мединский курс (Том 1)', '16', 'جَمْعُ غَيْرِ الْعَاقِلِ يُعَامَلُ مُعَامَلَةَ الْمُفْرَدَةِ الْمُؤَنَّثَةِ (неразумное множественное согласуется как женское единственное)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">جَمْعُ غَيْرِ الْعَاقِلِ يُعَامَلُ مُعَامَلَةَ الْمُفْرَدَةِ الْمُؤَنَّثَةِ</span><p class="rule-study-text">неразумное множественное согласуется как женское единственное. Множественное число слов, обозначающих людей, согласуется как множественное: هَؤُلَاءِ طُلَّابٌ جُدُدٌ. هُمْ صِغَارٌ. Множественное число предметов, животных и отвлечённых понятий в основной учебной модели согласуется как женское единственное. هَذِهِ كُتُبٌ جَدِيدَةٌ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذِهِ</span><span class="rule-term-ru">эта: указательное имя для близкого женского рода</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَؤُلَاءِ</span><span class="rule-term-ru">эти: указательное имя для множественного разумных</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">هَذِهِ كُتُبٌ جَدِيدَةٌ. هِيَ صَغِيرَةٌ.</span><span class="rule-example-ru">Это новые книги. Они маленькие.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">هَذِهِ كِلَابٌ. خَرَجَتْ.</span><span class="rule-example-ru">Это собаки. Они вышли.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">Множественное число слов, обозначающих людей, согласуется как множественное: <b>هَؤُلَاءِ طُلَّابٌ جُدُدٌ. هُمْ صِغَارٌ.</b> Множественное число предметов, животных и отвлечённых понятий в основной учебной модели согласуется как женское единственное.<br><br><ul><li><b>هَذِهِ كُتُبٌ جَدِيدَةٌ. هِيَ صَغِيرَةٌ.</b> — Это новые книги. Они маленькие.</li><li><b>هَذِهِ كِلَابٌ. خَرَجَتْ.</b> — Это собаки. Они вышли.</li></ul><br><br><b>Суть правила:</b> несмотря на русский перевод «они», в арабском употребляются <b>هَذِهِ، هِيَ</b>, женское прилагательное и глагол женского единственного числа.<br><br><b>Дополнительное объяснение.</b> Термины: люди — <b>عَاقِلٌ</b>, неодушевлённое/неразумное — <b>غَيْرُ عَاقِلٍ</b>. В учебнике правило даётся как базовое; стилистические и контекстные исключения изучаются позже.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 1, 'rule', 'Название и смысл جَمْعُ غَيْرِ الْعَاقِلِ يُعَامَلُ مُعَامَلَةَ الْمُفْرَدَةِ الْمُؤَنَّثَةِ неразумное множественное согласуется как женское единственное. Множественное число слов, обозначающих людей, согласуется как множественное: هَؤُلَا'),
('Мединский курс (Том 1)', '16', 'أَمْثِلَةٌ عَلَى جَمْعِ التَّكْسِيرِ (образцы ломаного множественного)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">أَمْثِلَةٌ عَلَى جَمْعِ التَّكْسِيرِ</span><p class="rule-study-text">образцы ломаного множественного. В уроке встречаются модели مَفَاعِلُ : مَسْجِدٌ ← مَسَاجِدُ , دَفْتَرٌ ← دَفَاتِرُ . Здесь это только распознавание формы множественного числа. Правило о том, что часть таких форм является مَمْنُوعًا مِنَ الصَّرْفِ и не принимает танвин, вводится строго позже, в уроке 22.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَمْثِلَةٌ عَلَى جَمْعِ التَّكْسِيرِ</span><span class="rule-term-ru">образцы ломаного множественного</span></div><div class="rule-meaning-card rule-term-role"><span class="rule-term-ar" dir="rtl" lang="ar">مَفَاعِلُ</span><span class="rule-term-ru">модель ломаного множественного числа, относящаяся к диптотам</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَمْنُوعًا مِنَ الصَّرْفِ</span><span class="rule-term-ru">диптот в винительном выражении: слово, запрещённое от танвина</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-role"><span class="rule-term-ar" dir="rtl" lang="ar">فَاعِلٌ</span><span class="rule-term-ru">действующее лицо, подлежащее при глаголе</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите предлог حَرْفُ جَرٍّ.</li><li>Слово после него поставьте как مَجْرُورٌ.</li><li>Переведите связь места, направления, источника или принадлежности по контексту.</li></ol></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">В уроке встречаются модели <b>مَفَاعِلُ</b>: <b>مَسْجِدٌ ← مَسَاجِدُ</b>, <b>دَفْتَرٌ ← دَفَاتِرُ</b>. Здесь это только распознавание формы множественного числа. Правило о том, что часть таких форм является <b>مَمْنُوعًا مِنَ الصَّرْفِ</b> и не принимает танвин, вводится строго позже, в уроке 22.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> После предлога нельзя оставлять имя как مَرْفُوعٌ: нужен جَرّ, обычно касра или танвин касры.</div></div>', 2, 'rule', 'Название и смысл أَمْثِلَةٌ عَلَى جَمْعِ التَّكْسِيرِ образцы ломаного множественного. В уроке встречаются модели مَفَاعِلُ : مَسْجِدٌ ← مَسَاجِدُ , دَفْتَرٌ ← دَفَاتِرُ . Здесь это только распознавание формы множественного числа. Правило о'),
('Мединский курс (Том 1)', '17', 'الْمُبْتَدَأُ وَالْخَبَرُ (мубтада и хабар)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمُبْتَدَأُ وَالْخَبَرُ</span><p class="rule-study-text">мубтада и хабар. Это продолжение урока 16. Авторский ключ прямо указывает: новых конструкций нет. Суть правила. الْمُبْتَدَأُ — то, о чём говорится; الْخَبَرُ — сообщение о нём.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُبْتَدَأُ وَالْخَبَرُ</span><span class="rule-term-ru">мубтада и хабар</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُبْتَدَأُ</span><span class="rule-term-ru">подлежащее именного предложения; первый главный член الجُمْلَةُ الِاسْمِيَّةُ</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar" dir="rtl" lang="ar">الْخَبَرُ</span><span class="rule-term-ru">сказуемое / сообщение о الْمُبْتَدَأُ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الْبَيْتُ</span><span class="rule-term-ru">мубтада, كَبِيرٌ — хабар</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">النُّجُومُ</span><span class="rule-term-ru">мубтада, جَمِيلَةٌ — хабар</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">مُبْتَدَأٌ</span><span class="rule-term-ru">подлежащее именного предложения</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar" dir="rtl" lang="ar">خَبَرٌ</span><span class="rule-term-ru">сказуемое / сообщение о مُبْتَدَأٌ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите مُبْتَدَأٌ: о ком или о чём говорится.</li><li>Найдите خَبَرٌ: что сообщается.</li><li>Оба главных члена обычно مَرْفُوعٌ.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">الْبَيْتُ كَبِيرٌ.</span><span class="rule-example-ru">Дом большой. الْبَيْتُ — мубтада, كَبِيرٌ — хабар.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">النُّجُومُ جَمِيلَةٌ.</span><span class="rule-example-ru">Звёзды красивые. النُّجُومُ — мубтада, جَمِيلَةٌ — хабар; при неразумном множественном числе хабар имеет форму женского единственного числа.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">فِي الْهِنْدِ لُغَاتٌ كَثِيرَةٌ.</span><span class="rule-example-ru">В Индии много языков. Предложная группа стоит впереди, а لُغَاتٌ является сообщаемым словом.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">Это продолжение урока 16. Авторский ключ прямо указывает: новых конструкций нет.<br><br><b>Суть правила.</b> <b>الْمُبْتَدَأُ</b> — то, о чём говорится; <b>الْخَبَرُ</b> — сообщение о нём. В простой именной фразе оба обычно стоят в именительном падеже.<br><br><ul><li><b>الْبَيْتُ كَبِيرٌ.</b> — Дом большой. <b>الْبَيْتُ</b> — мубтада, <b>كَبِيرٌ</b> — хабар.</li><li><b>النُّجُومُ جَمِيلَةٌ.</b> — Звёзды красивые. <b>النُّجُومُ</b> — мубтада, <b>جَمِيلَةٌ</b> — хабар; при неразумном множественном числе хабар имеет форму женского единственного числа.</li><li><b>فِي الْهِنْدِ لُغَاتٌ كَثِيرَةٌ.</b> — В Индии много языков. Предложная группа стоит впереди, а <b>لُغَاتٌ</b> является сообщаемым словом.</li></ul><br><br><b>Дополнительное объяснение.</b> В упражнениях урока 17 отдельно предлагается «вписать хабар». Не нужно считать, что хабар всегда одно прилагательное: им может быть существительное или предложная группа. Главное — определить, что именно сообщается о мубтада.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не называйте любое первое слово مُبْتَدَأٌ автоматически: сначала проверьте, даёт ли второе слово законченное сообщение.</div></div>', 1, 'rule', 'Название и смысл الْمُبْتَدَأُ وَالْخَبَرُ мубтада и хабар. Это продолжение урока 16. Авторский ключ прямо указывает: новых конструкций нет. Суть правила. الْمُبْتَدَأُ — то, о чём говорится; الْخَبَرُ — сообщение о нём. Арабские слова → ру'),
('Мединский курс (Том 1)', '17', 'تَثْبِيتُ قَاعِدَةِ جَمْعِ غَيْرِ الْعَاقِلِ (закрепление согласования неразумного множественного)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">تَثْبِيتُ قَاعِدَةِ جَمْعِ غَيْرِ الْعَاقِلِ</span><p class="rule-study-text">закрепление согласования неразумного множественного. هَذِهِ شَرِكَاتٌ يَابَانِيَّةٌ. — Это японские компании. الْقُمُصُ رَخِيصَةٌ. — Рубашки дешёвые.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">تَثْبِيتُ قَاعِدَةِ جَمْعِ غَيْرِ الْعَاقِلِ</span><span class="rule-term-ru">закрепление согласования неразумного множественного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذِهِ</span><span class="rule-term-ru">эта: указательное имя для близкого женского рода</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">هَذِهِ شَرِكَاتٌ يَابَانِيَّةٌ.</span><span class="rule-example-ru">Это японские компании.</span></div><div class="rule-example-card rule-term-default"><span class="rule-example-ar" dir="rtl" lang="ar">الْقُمُصُ رَخِيصَةٌ.</span><span class="rule-example-ru">Рубашки дешёвые.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><ul><li><b>هَذِهِ شَرِكَاتٌ يَابَانِيَّةٌ.</b> — Это японские компании.</li><li><b>الْقُمُصُ رَخِيصَةٌ.</b> — Рубашки дешёвые.</li></ul><br><br>Следует тренировать замену подлежащего на множественное, подбор сказуемого женского единственного и словарные формы ломаного множественного. Например, у <b>حِمَارٌ</b> возможны формы <b>حُمُرٌ</b> и <b>حَمِيرٌ</b>.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 2, 'rule', 'Название и смысл تَثْبِيتُ قَاعِدَةِ جَمْعِ غَيْرِ الْعَاقِلِ закрепление согласования неразумного множественного. هَذِهِ شَرِكَاتٌ يَابَانِيَّةٌ. — Это японские компании. الْقُمُصُ رَخِيصَةٌ. — Рубашки дешёвые. Арабские слова → русский смы'),
('Мединский курс (Том 1)', '17', 'مُطَابَقَةُ الْخَبَرِ لِلْمُبْتَدَأِ (согласование хабар с мубтада)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">مُطَابَقَةُ الْخَبَرِ لِلْمُبْتَدَأِ</span><p class="rule-study-text">согласование хабар с мубтада. الْخَبَرُ согласуется с الْمُبْتَدَأُ по смыслу, роду и числу, если хабар выражен описательным именем. الطَّالِبُ طَوِيلٌ — Студент высокий. الطَّالِبَةُ مُجْتَهِدَةٌ — Студентка усердная. الطُّلَّابُ طِوَالٌ — Студенты высокие.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">مُطَابَقَةُ الْخَبَرِ لِلْمُبْتَدَأِ</span><span class="rule-term-ru">согласование хабар с мубтада</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar" dir="rtl" lang="ar">الْخَبَرُ</span><span class="rule-term-ru">сказуемое / сообщение о الْمُبْتَدَأُ</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُبْتَدَأُ</span><span class="rule-term-ru">подлежащее именного предложения; первый главный член الجُمْلَةُ الِاسْمِيَّةُ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الطَّالِبُ طَوِيلٌ</span><span class="rule-term-ru">Студент высокий</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الطَّالِبَةُ مُجْتَهِدَةٌ</span><span class="rule-term-ru">Студентка усердная</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الطُّلَّابُ طِوَالٌ</span><span class="rule-term-ru">Студенты высокие</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الأَقْلَامُ جَمِيلَةٌ</span><span class="rule-term-ru">Ручки красивые</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">مُبْتَدَأٌ</span><span class="rule-term-ru">подлежащее именного предложения</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar" dir="rtl" lang="ar">خَبَرٌ</span><span class="rule-term-ru">сказуемое / сообщение о مُبْتَدَأٌ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите مُبْتَدَأٌ: о ком или о чём говорится.</li><li>Найдите خَبَرٌ: что сообщается.</li><li>Оба главных члена обычно مَرْفُوعٌ.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">الطَّالِبُ طَوِيلٌ</span><span class="rule-example-ru">Студент высокий.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">الطَّالِبَةُ مُجْتَهِدَةٌ</span><span class="rule-example-ru">Студентка усердная.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">الطُّلَّابُ طِوَالٌ</span><span class="rule-example-ru">Студенты высокие.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar" dir="rtl" lang="ar">الأَقْلَامُ جَمِيلَةٌ</span><span class="rule-example-ru">Ручки красивые.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><p><b>الْخَبَرُ</b> согласуется с <b>الْمُبْتَدَأُ</b> по смыслу, роду и числу, если хабар выражен описательным именем.</p><ul><li>الطَّالِبُ طَوِيلٌ — Студент высокий.</li><li>الطَّالِبَةُ مُجْتَهِدَةٌ — Студентка усердная.</li><li>الطُّلَّابُ طِوَالٌ — Студенты высокие.</li><li>الأَقْلَامُ جَمِيلَةٌ — Ручки красивые.</li></ul><p>Для множественного числа неразумных предметов хабар часто приходит как женский род единственного числа: <b>الأَقْلَامُ جَمِيلَةٌ</b>.</p></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не называйте любое первое слово مُبْتَدَأٌ автоматически: сначала проверьте, даёт ли второе слово законченное сообщение.</div></div>', 3, 'rule', 'Название и смысл مُطَابَقَةُ الْخَبَرِ لِلْمُبْتَدَأِ согласование хабар с мубтада. الْخَبَرُ согласуется с الْمُبْتَدَأُ по смыслу, роду и числу, если хабар выражен описательным именем. الطَّالِبُ طَوِيلٌ — Студент высокий. الطَّالِبَةُ مُ'),
('Мединский курс (Том 1)', '18', 'الْمُثَنَّى وَعَلَامَةُ الرَّفْعِ: ـَانِ (двойственное число в именительном падеже)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمُثَنَّى وَعَلَامَةُ الرَّفْعِ: ـَانِ</span><p class="rule-study-text">двойственное число в именительном падеже. Двойственное число обозначает ровно два предмета или лица. В именительном падеже к основе добавляется ـَانِ . وَلَدٌ ← وَلَدَانِ — мальчик → два мальчика. بِنْتٌ ← بِنْتَانِ — девочка → две девочки.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُثَنَّى وَعَلَامَةُ الرَّفْعِ: ـَانِ</span><span class="rule-term-ru">двойственное число в именительном падеже</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">وَلَدَانِ</span><span class="rule-term-ru">мальчик → два мальчика</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">بِنْتَانِ</span><span class="rule-term-ru">девочка → две девочки</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ـَيْنِ</span><span class="rule-term-ru">رَأَيْتُ طَالِبَيْنِ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">это / этот: указательное имя для близкого мужского рода</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْمُثَنَّى</span><span class="rule-term-ru">двойственное число</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Проверьте, что речь ровно о двух предметах или лицах.</li><li>В رَفْع обычно используется окончание ـَانِ.</li><li>В نَصْب и جَرّ используется ـَيْنِ.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">وَلَدٌ ← وَلَدَانِ</span><span class="rule-example-ru">мальчик → два мальчика.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">بِنْتٌ ← بِنْتَانِ</span><span class="rule-example-ru">девочка → две девочки.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">هَذَانِ كِتَابَانِ جَدِيدَانِ.</span><span class="rule-example-ru">Это две новые книги.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar" dir="rtl" lang="ar">هَاتَانِ سَيَّارَتَانِ جَدِيدَتَانِ.</span><span class="rule-example-ru">Это две новые машины.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">Двойственное число обозначает ровно два предмета или лица. В именительном падеже к основе добавляется <b>ـَانِ</b>.<br><br><ul><li><b>وَلَدٌ ← وَلَدَانِ</b> — мальчик → два мальчика.</li><li><b>بِنْتٌ ← بِنْتَانِ</b> — девочка → две девочки.</li><li><b>هَذَانِ كِتَابَانِ جَدِيدَانِ.</b> — Это две новые книги.</li><li><b>هَاتَانِ سَيَّارَتَانِ جَدِيدَتَانِ.</b> — Это две новые машины.</li></ul><br><br>Определение при двойственном существительном тоже ставится в двойственное число.<br><br><b>Дополнительное объяснение.</b> Винительный и родительный падежи двойственного имеют окончание <b>ـَيْنِ</b>: <b>رَأَيْتُ طَالِبَيْنِ، مَرَرْتُ بِطَالِبَيْنِ</b>. Хотя основной материал урока сосредоточен на <b>ـَانِ</b>, база не должна утверждать, что это единственное окончание двойственного.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Нельзя переводить двойственное как обычное множественное: оно означает именно «два / две».</div></div>', 1, 'rule', 'Название и смысл الْمُثَنَّى وَعَلَامَةُ الرَّفْعِ: ـَانِ двойственное число в именительном падеже. Двойственное число обозначает ровно два предмета или лица. В именительном падеже к основе добавляется ـَانِ . وَلَدٌ ← وَلَدَانِ — мальчик →'),
('Мединский курс (Том 1)', '18', 'كَمِ الِاسْتِفْهَامِيَّةُ وَتَمْيِيزُهَا (вопрос «сколько?»)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">كَمِ الِاسْتِفْهَامِيَّةُ وَتَمْيِيزُهَا</span><p class="rule-study-text">вопрос «сколько?». После вопросительного كَمْ считаемое слово в модели урока ставится в единственном числе винительного падежа. كَمْ كِتَابًا عِنْدَكَ؟ — Сколько у тебя книг? كَمْ سَيَّارَةً عِنْدَ الْمُدِيرِ؟</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">كَمِ الِاسْتِفْهَامِيَّةُ وَتَمْيِيزُهَا</span><span class="rule-term-ru">вопрос «сколько?»</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar" dir="rtl" lang="ar">تَمْيِيزٌ</span><span class="rule-term-ru">поясняющее слово после كَمْ и чисел</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">كَمْ</span><span class="rule-term-ru">сколько?: вопросительное имя числа</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число.</li><li>Проверьте род единственного числа الْمَعْدُودُ.</li><li>После كَمْ ставьте تَمْيِيزٌ в نَصْب, а после 3-10 - множественное в جَرّ.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">كَمْ كِتَابًا عِنْدَكَ؟</span><span class="rule-example-ru">Сколько у тебя книг?</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar" dir="rtl" lang="ar">كَمْ سَيَّارَةً عِنْدَ الْمُدِيرِ؟</span><span class="rule-example-ru">Сколько машин у директора?</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">После вопросительного <b>كَمْ</b> считаемое слово в модели урока ставится в единственном числе винительного падежа.<br><br><ul><li><b>كَمْ كِتَابًا عِنْدَكَ؟</b> — Сколько у тебя книг?</li><li><b>كَمْ سَيَّارَةً عِنْدَ الْمُدِيرِ؟</b> — Сколько машин у директора?</li></ul><br><br>Слово после <b>كَمْ</b> называется <b>تَمْيِيزٌ</b>. У слова с <b>ة</b> добавочная алиф винительного танвина не пишется: <b>سَيَّارَةً</b>, не <b>سَيَّارَةًا</b>.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Для чисел 3-10 род числительного противоположен роду единственного числа считаемого слова.</div></div>', 2, 'rule', 'Название и смысл كَمِ الِاسْتِفْهَامِيَّةُ وَتَمْيِيزُهَا вопрос «сколько?». После вопросительного كَمْ считаемое слово в модели урока ставится в единственном числе винительного падежа. كَمْ كِتَابًا عِنْدَكَ؟ — Сколько у тебя книг? كَمْ سَ'),
('Мединский курс (Том 1)', '19', 'الْعَدَدَانِ وَاحِدٌ وَاثْنَانِ (числа один и два)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْعَدَدَانِ وَاحِدٌ وَاثْنَانِ</span><p class="rule-study-text">числа один и два. وَاحِدٌ обычно стоит после существительного и согласуется с ним: كِتَابٌ وَاحِدٌ . Число два обычно выражено самой двойственной формой, поэтому اِثْنَانِ можно опустить: كِتَابَانِ уже означает «две книги».</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْعَدَدَانِ وَاحِدٌ وَاثْنَانِ</span><span class="rule-term-ru">числа один и два</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْعَدَدُ</span><span class="rule-term-ru">числительное</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число.</li><li>Проверьте род единственного числа الْمَعْدُودُ.</li><li>После كَمْ ставьте تَمْيِيزٌ в نَصْب, а после 3-10 - множественное в جَرّ.</li></ol></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>وَاحِدٌ</b> обычно стоит после существительного и согласуется с ним: <b>كِتَابٌ وَاحِدٌ</b>. Число два обычно выражено самой двойственной формой, поэтому <b>اِثْنَانِ</b> можно опустить: <b>كِتَابَانِ</b> уже означает «две книги».</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Для чисел 3-10 род числительного противоположен роду единственного числа считаемого слова.</div></div>', 1, 'rule', 'Название и смысл الْعَدَدَانِ وَاحِدٌ وَاثْنَانِ числа один и два. وَاحِدٌ обычно стоит после существительного и согласуется с ним: كِتَابٌ وَاحِدٌ . Число два обычно выражено самой двойственной формой, поэтому اِثْنَانِ можно опустить: كِت'),
('Мединский курс (Том 1)', '19', 'الْأَعْدَادُ مِنْ ثَلَاثَةٍ إِلَى عَشَرَةٍ مَعَ الْمَعْدُودِ الْمُذَكَّرِ (3–10 с существительным мужского рода)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْأَعْدَادُ مِنْ ثَلَاثَةٍ إِلَى عَشَرَةٍ مَعَ الْمَعْدُودِ الْمُذَكَّرِ</span><p class="rule-study-text">3–10 с существительным мужского рода. С мужским считаемым существительным употребляется форма числа с ة : ثَلَاثَةُ، أَرْبَعَةُ، خَمْسَةُ، سِتَّةُ، سَبْعَةُ، ثَمَانِيَةُ، تِسْعَةُ، عَشَرَةُ . Считаемое слово ставится во множественном числе родительного падежа: ثَلَاثَةُ كُتُبٍ، أَرْبَعَةُ بُيُوتٍ، خَمْسَةُ أَقْلَامٍ، عَشَرَةُ رِجَالٍ . عِنْدِي ثَلَاثَةُ كُتُبٍ. — У меня три книги.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مُضَافٌ</span><span class="rule-term-ru">первый член идафы</span></div><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">مُضَافٌ إِلَيْهِ</span><span class="rule-term-ru">второй член идафы, всегда مَجْرُورٌ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ة</span><span class="rule-term-ru">ثَلَاثَةُ</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْمَعْدُودُ</span><span class="rule-term-ru">считаемое слово</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число.</li><li>Проверьте род единственного числа الْمَعْدُودُ.</li><li>После كَمْ ставьте تَمْيِيزٌ в نَصْب, а после 3-10 - множественное в جَرّ.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">عِنْدِي ثَلَاثَةُ كُتُبٍ.</span><span class="rule-example-ru">У меня три книги.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">رَأَيْتُ خَمْسَةَ رِجَالٍ.</span><span class="rule-example-ru">Я видел пятерых мужчин.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">С мужским считаемым существительным употребляется форма числа с <b>ة</b>: <b>ثَلَاثَةُ، أَرْبَعَةُ، خَمْسَةُ، سِتَّةُ، سَبْعَةُ، ثَمَانِيَةُ، تِسْعَةُ، عَشَرَةُ</b>.<br><br>Считаемое слово ставится во множественном числе родительного падежа: <b>ثَلَاثَةُ كُتُبٍ، أَرْبَعَةُ بُيُوتٍ، خَمْسَةُ أَقْلَامٍ، عَشَرَةُ رِجَالٍ</b>.<br><br><ul><li><b>عِنْدِي ثَلَاثَةُ كُتُبٍ.</b> — У меня три книги.</li><li><b>رَأَيْتُ خَمْسَةَ رِجَالٍ.</b> — Я видел пятерых мужчин.</li></ul><br><br><b>Дополнительное объяснение.</b> Числительное является <b>مُضَافٌ</b>, а множественное считаемое — <b>مُضَافٌ إِلَيْهِ</b>. Падеж числа зависит от его роли; форма считаемого остаётся родительной.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Для чисел 3-10 род числительного противоположен роду единственного числа считаемого слова.</div></div>', 2, 'rule', 'Название и смысл الْأَعْدَادُ مِنْ ثَلَاثَةٍ إِلَى عَشَرَةٍ مَعَ الْمَعْدُودِ الْمُذَكَّرِ 3–10 с существительным мужского рода. С мужским считаемым существительным употребляется форма числа с ة : ثَلَاثَةُ، أَرْبَعَةُ، خَمْسَةُ، سِتَّةُ، س'),
('Мединский курс (Том 1)', '20', 'الْأَعْدَادُ مِنْ ثَلَاثَةٍ إِلَى عَشَرَةٍ مَعَ الْمَعْدُودِ الْمُؤَنَّثِ (3–10 с существительным женского рода)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْأَعْدَادُ مِنْ ثَلَاثَةٍ إِلَى عَشَرَةٍ مَعَ الْمَعْدُودِ الْمُؤَنَّثِ</span><p class="rule-study-text">3–10 с существительным женского рода. С существительным женского рода употребляется форма числа без ة : ثَلَاثُ، أَرْبَعُ، خَمْسُ، سِتُّ، سَبْعُ، ثَمَانِي، تِسْعُ، عَشْرُ . ثَلَاثُ بَنَاتٍ — три девочки. أَرْبَعُ أَخَوَاتٍ — четыре сестры. خَمْسُ أُمَّهَاتٍ — пять матерей.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ة</span><span class="rule-term-ru">ثَلَاثُ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ثَلَاثُ بَنَاتٍ</span><span class="rule-term-ru">три девочки</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَرْبَعُ أَخَوَاتٍ</span><span class="rule-term-ru">четыре сестры</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">خَمْسُ أُمَّهَاتٍ</span><span class="rule-term-ru">пять матерей</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">سَبْعُ طَالِبَاتٍ</span><span class="rule-term-ru">семь студенток</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">عَشْرُ نِسَاءٍ</span><span class="rule-term-ru">десять женщин</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">بَيْتٌ</span><span class="rule-term-ru">мужской род, поэтому ثَلَاثَةُ بُيُوتٍ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">سَيَّارَةٌ</span><span class="rule-term-ru">женский род, поэтому ثَلَاثُ سَيَّارَاتٍ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">وَاحِدٌ، اِثْنَانِ</span><span class="rule-term-ru">وَاحِدَةٌ</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите число.</li><li>Проверьте род единственного числа الْمَعْدُودُ.</li><li>После كَمْ ставьте تَمْيِيزٌ в نَصْب, а после 3-10 - множественное в جَرّ.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">ثَلَاثُ بَنَاتٍ</span><span class="rule-example-ru">три девочки.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">أَرْبَعُ أَخَوَاتٍ</span><span class="rule-example-ru">четыре сестры.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">خَمْسُ أُمَّهَاتٍ</span><span class="rule-example-ru">пять матерей.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">سَبْعُ طَالِبَاتٍ</span><span class="rule-example-ru">семь студенток.</span></div><div class="rule-example-card rule-term-structure"><span class="rule-example-ar" dir="rtl" lang="ar">عَشْرُ نِسَاءٍ</span><span class="rule-example-ru">десять женщин.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">С существительным женского рода употребляется форма числа без <b>ة</b>: <b>ثَلَاثُ، أَرْبَعُ، خَمْسُ، سِتُّ، سَبْعُ، ثَمَانِي، تِسْعُ، عَشْرُ</b>.<br><br><ul><li><b>ثَلَاثُ بَنَاتٍ</b> — три девочки.</li><li><b>أَرْبَعُ أَخَوَاتٍ</b> — четыре сестры.</li><li><b>خَمْسُ أُمَّهَاتٍ</b> — пять матерей.</li><li><b>سَبْعُ طَالِبَاتٍ</b> — семь студенток.</li><li><b>عَشْرُ نِسَاءٍ</b> — десять женщин.</li></ul><br><br>Считаемое слово, как и в уроке 19, стоит во множественном числе родительного падежа.<br><br><b>Определение рода.</b> Род числительного выбирается по форме единственного числа: <b>بَيْتٌ</b> — мужской род, поэтому <b>ثَلَاثَةُ بُيُوتٍ</b>; <b>سَيَّارَةٌ</b> — женский род, поэтому <b>ثَلَاثُ سَيَّارَاتٍ</b>.<br><br><b>Формы чисел.</b> Женские соответствия <b>وَاحِدٌ، اِثْنَانِ</b>: <b>وَاحِدَةٌ، اِثْنَتَانِ</b>.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Для чисел 3-10 род числительного противоположен роду единственного числа считаемого слова.</div></div>', 1, 'rule', 'Название и смысл الْأَعْدَادُ مِنْ ثَلَاثَةٍ إِلَى عَشَرَةٍ مَعَ الْمَعْدُودِ الْمُؤَنَّثِ 3–10 с существительным женского рода. С существительным женского рода употребляется форма числа без ة : ثَلَاثُ، أَرْبَعُ، خَمْسُ، سِتُّ، سَبْعُ، ثَم'),
('Мединский курс (Том 1)', '21', 'دَرْسُ مُرَاجَعَةٍ (контрольный урок)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">دَرْسُ مُرَاجَعَةٍ</span><p class="rule-study-text">контрольный урок. Авторский ключ прямо указывает: новых грамматических конструкций нет. Урок проверяет пройденные темы и вводит несколько слов, среди которых الْآنَ — сейчас, قَالَ — он сказал, آسِيَا — Азия. В базе правил урок 21 не следует заполнять вымышленным новым правилом. Его назначение: повторение местоимений и суффиксов; повторение прошедшего времени; повторение идафы, прилагательных, множественного числа и числительных; диагностический тест перед темой الْمَمْنُوعُ مِنَ الصَّرْفِ .</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">دَرْسُ مُرَاجَعَةٍ</span><span class="rule-term-ru">контрольный урок</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْمَمْنُوعُ مِنَ الصَّرْفِ</span><span class="rule-term-ru">диптот: слово без танвина, с особым جَرّ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">الْآنَ</span><span class="rule-term-ru">сейчас, قَالَ — он сказал, آسِيَا — Азия</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">قَالَ الْمُدَرِّسُ</span><span class="rule-term-ru">هَؤُلَاءِ طُلَّابٌ جُدُدٌ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَؤُلَاءِ</span><span class="rule-term-ru">эти: указательное имя для множественного разумных</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَمْنُوعٌ مِنَ الصَّرْفِ</span><span class="rule-term-ru">диптот: слово без танвина, с особым جَرّ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Определите близость: близко или далеко.</li><li>Определите род и число того, на что указывают.</li><li>Проверьте: после указательного слова часто идёт имя, раскрывающее, на что указывают.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar" dir="rtl" lang="ar">قَالَ الْمُدَرِّسُ: هَؤُلَاءِ طُلَّابٌ جُدُدٌ.</span><span class="rule-example-ru">Учитель сказал: «Это новые студенты».</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">Авторский ключ прямо указывает: новых грамматических конструкций нет. Урок проверяет пройденные темы и вводит несколько слов, среди которых <b>الْآنَ</b> — сейчас, <b>قَالَ</b> — он сказал, <b>آسِيَا</b> — Азия.<br><br>В базе правил урок 21 не следует заполнять вымышленным новым правилом. Его назначение:<br><br><ul><li>повторение местоимений и суффиксов;</li><li>повторение прошедшего времени;</li><li>повторение идафы, прилагательных, множественного числа и числительных;</li><li>диагностический тест перед темой <b>الْمَمْنُوعُ مِنَ الصَّرْفِ</b>.</li></ul><br><br>Пример повторения:<br><br><ul><li><b>قَالَ الْمُدَرِّسُ: هَؤُلَاءِ طُلَّابٌ جُدُدٌ.</b> — Учитель сказал: «Это новые студенты».</li></ul><br><br>Следовательно, правило <b>لِأَنَّ</b> нельзя относить к уроку 21 первого тома: в авторском поурочном ключе этого урока такой новой конструкции нет.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Не смешивайте формы: هَذَا для близкого мужского, هَذِهِ для близкого женского, ذَلِكَ/تِلْكَ для далёкого.</div></div>', 1, 'note', 'Название и смысл دَرْسُ مُرَاجَعَةٍ контрольный урок. Авторский ключ прямо указывает: новых грамматических конструкций нет. Урок проверяет пройденные темы и вводит несколько слов, среди которых الْآنَ — сейчас, قَالَ — он сказал, آسِيَا — А'),
('Мединский курс (Том 1)', '22', 'الْمَمْنُوعُ مِنَ الصَّرْفِ: عَدَمُ التَّنْوِينِ (диптоты: отсутствие танвина)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">الْمَمْنُوعُ مِنَ الصَّرْفِ: عَدَمُ التَّنْوِينِ</span><p class="rule-study-text">диптоты: отсутствие танвина. Суть правила. Некоторые существительные и прилагательные не принимают танвин. В именительном падеже у них одна дамма: أَحْمَدُ، مَسَاجِدُ , а не أَحْمَدٌ، مَسَاجِدٌ . Дополнительное объяснение.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْمَمْنُوعُ مِنَ الصَّرْفِ: عَدَمُ التَّنْوِينِ</span><span class="rule-term-ru">диптоты: отсутствие танвина</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَمْنُوعٌ مِنَ الصَّرْفِ</span><span class="rule-term-ru">диптот: слово без танвина, с особым جَرّ</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar" dir="rtl" lang="ar">إِبْرَاهِيمُ، إِسْمَاعِيلُ، إِسْحَاقُ، بَغْدَادُ</span><span class="rule-term-ru">примеры диптотов: имена и название города без танвина</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ة</span><span class="rule-term-ru">حَمْزَةُ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">ـَانُ</span><span class="rule-term-ru">عُثْمَانُ</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">فَعْلَانُ</span><span class="rule-term-ru">عَطْشَانُ</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar" dir="rtl" lang="ar">أَفْعَلُ</span><span class="rule-term-ru">أَحْمَدُ</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَا</span><span class="rule-term-ru">что?: вопросительное имя для неразумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Проверьте, относится ли слово к группе الْمَمْنُوعُ مِنَ الصَّرْفِ.</li><li>Не ставьте танвин.</li><li>В جَرّ без أَلْـ и без идафы ставьте фатху вместо касры.</li></ol></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text"><b>Суть правила.</b> Некоторые существительные и прилагательные не принимают танвин. В именительном падеже у них одна дамма: <b>أَحْمَدُ، مَسَاجِدُ</b>, а не <b>أَحْمَدٌ، مَسَاجِدٌ</b>.<br><br><b>Дополнительное объяснение.</b> Термин <b>مَمْنُوعٌ مِنَ الصَّرْفِ</b> не означает «совсем не изменяется». Такое слово изменяется по падежам, но обычно не имеет танвина и в родительном падеже без артикля/идафы получает фатху.<br><br>Группы, перечисленные в уроке:<br><br>1. Женские собственные имена: <b>آمِنَةُ، زَيْنَبُ</b>.<br>2. Мужские имена с конечной <b>ة</b>: <b>حَمْزَةُ، مُعَاوِيَةُ</b>.<br>3. Мужские имена на <b>ـَانُ</b>: <b>عُثْمَانُ، سُلَيْمَانُ</b>.<br>4. Прилагательные на <b>فَعْلَانُ</b>: <b>عَطْشَانُ، غَضْبَانُ</b>.<br>5. Мужские имена на модели <b>أَفْعَلُ</b>: <b>أَحْمَدُ، أَكْرَمُ</b>.<br>6. Цвета и подобные прилагательные на <b>أَفْعَلُ</b>: <b>أَحْمَرُ، أَسْوَدُ، أَصْفَرُ، أَبْيَضُ</b>.<br>7. Большинство иноязычных собственных имён: <b>إِبْرَاهِيمُ، إِسْمَاعِيلُ، إِسْحَاقُ، بَغْدَادُ</b>; применяются оговорённые в уроке исключения.<br>8. Некоторые модели ломаного множественного <b>صِيغَةُ مُنْتَهَى الْجُمُوعِ</b>, например <b>مَسَاجِدُ، مَفَاتِيحُ، فَنَادِقُ، دَقَائِقُ</b>.<br><br>База не должна формулировать это как «все женские имена» или «все иностранные слова» без условий.</div></div><div class="rule-check-card"><b>Частая ошибка.</b> Диптот не «полностью неизменяемый»: он меняет падеж, но без танвина и с особым родительным падежом.</div></div>', 1, 'rule', 'Название и смысл الْمَمْنُوعُ مِنَ الصَّرْفِ: عَدَمُ التَّنْوِينِ диптоты: отсутствие танвина. Суть правила. Некоторые существительные и прилагательные не принимают танвин. В именительном падеже у них одна дамма: أَحْمَدُ، مَسَاجِدُ , а не '),
('Мединский курс (Том 1)', '23', 'جَرُّ الْمَمْنُوعِ مِنَ الصَّرْفِ بِالْفَتْحَةِ (родительный падеж диптота с фатхой)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">جَرُّ الْمَمْنُوعِ مِنَ الصَّرْفِ بِالْفَتْحَةِ</span><p class="rule-study-text">родительный падеж диптота с фатхой. Если слово مَمْنُوعٌ مِنَ الصَّرْفِ стоит после предлога или как второй член идафы, но не имеет أَلْـ и само не является первым членом идафы, оно получает фатху вместо касры. أَحْمَدُ — Ахмад, именительный: هَذَا أَحْمَدُ. أَحْمَدَ — Ахмада, винительный: رَأَيْتُ أَحْمَدَ. أَحْمَدَ — Ахмада, родительный после предлога: مَرَرْتُ بِأَحْمَدَ.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-jarr"><span class="rule-term-ar" dir="rtl" lang="ar">جَرُّ الْمَمْنُوعِ مِنَ الصَّرْفِ بِالْفَتْحَةِ</span><span class="rule-term-ru">родительный падеж диптота с фатхой</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">مَمْنُوعٌ مِنَ الصَّرْفِ</span><span class="rule-term-ru">диптот: слово без танвина, с особым جَرّ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَحْمَدُ</span><span class="rule-term-ru">Ахмад, именительный: هَذَا أَحْمَدُ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَحْمَدَ</span><span class="rule-term-ru">Ахмада, винительный: رَأَيْتُ أَحْمَدَ</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مِنْ بَغْدَادَ</span><span class="rule-term-ru">из Багдада</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">فِي فَنَادِقَ</span><span class="rule-term-ru">в гостиницах</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">هَذَا</span><span class="rule-term-ru">это / этот: указательное имя для близкого мужского рода</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">مَنْ</span><span class="rule-term-ru">кто?: вопросительное имя для разумного</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَلْـ</span><span class="rule-term-ru">определённый артикль</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar" dir="rtl" lang="ar">الْمَمْنُوعُ مِنَ الصَّرْفِ</span><span class="rule-term-ru">диптот: слово без танвина, с особым جَرّ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Проверьте, относится ли слово к группе الْمَمْنُوعُ مِنَ الصَّرْفِ.</li><li>Не ставьте танвин.</li><li>В جَرّ без أَلْـ и без идафы ставьте фатху вместо касры.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">أَحْمَدُ</span><span class="rule-example-ru">Ахмад, именительный: هَذَا أَحْمَدُ.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">أَحْمَدَ</span><span class="rule-example-ru">Ахмада, винительный: رَأَيْتُ أَحْمَدَ.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">أَحْمَدَ</span><span class="rule-example-ru">Ахмада, родительный после предлога: مَرَرْتُ بِأَحْمَدَ.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">مِنْ بَغْدَادَ</span><span class="rule-example-ru">из Багдада.</span></div><div class="rule-example-card rule-term-jarr"><span class="rule-example-ar" dir="rtl" lang="ar">فِي فَنَادِقَ</span><span class="rule-example-ru">в гостиницах.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">Если слово <b>مَمْنُوعٌ مِنَ الصَّرْفِ</b> стоит после предлога или как второй член идафы, но не имеет <b>أَلْـ</b> и само не является первым членом идафы, оно получает фатху вместо касры.<br><br><ul><li><b>أَحْمَدُ</b> — Ахмад, именительный: <b>هَذَا أَحْمَدُ.</b></li><li><b>أَحْمَدَ</b> — Ахмада, винительный: <b>رَأَيْتُ أَحْمَدَ.</b></li><li><b>أَحْمَدَ</b> — Ахмада, родительный после предлога: <b>مَرَرْتُ بِأَحْمَدَ.</b></li><li><b>مِنْ بَغْدَادَ</b> — из Багдада.</li><li><b>فِي فَنَادِقَ</b> — в гостиницах.</li></ul></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Диптот не «полностью неизменяемый»: он меняет падеж, но без танвина и с особым родительным падежом.</div></div>', 1, 'rule', 'Название и смысл جَرُّ الْمَمْنُوعِ مِنَ الصَّرْفِ بِالْفَتْحَةِ родительный падеж диптота с фатхой. Если слово مَمْنُوعٌ مِنَ الصَّرْفِ стоит после предлога или как второй член идафы, но не имеет أَلْـ и само не является первым членом идаф'),
('Мединский курс (Том 1)', '23', 'عَوْدُ الْكَسْرَةِ مَعَ أَلْـ أَوِ الْإِضَافَةِ (возвращение касры с артиклем или в идафе)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Название и смысл</span><span class="rule-main-ar" dir="rtl" lang="ar">عَوْدُ الْكَسْرَةِ مَعَ أَلْـ أَوِ الْإِضَافَةِ</span><p class="rule-study-text">возвращение касры с артиклем или в идафе. Диптот получает обычную касру в родительном падеже, если он определён артиклем или является первым членом идафы. فِي الْمَسَاجِدِ — в мечетях. فِي مَسَاجِدِ الْمَدِينَةِ — в мечетях города. مَفَاتِيحُ الْفَنَادِقِ — ключи гостиниц; здесь الْفَنَادِقِ имеет артикль.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Арабские слова → русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">عَوْدُ الْكَسْرَةِ مَعَ أَلْـ أَوِ الْإِضَافَةِ</span><span class="rule-term-ru">возвращение касры с артиклем или в идафе</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">فِي الْمَسَاجِدِ</span><span class="rule-term-ru">в мечетях</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">فِي مَسَاجِدِ الْمَدِينَةِ</span><span class="rule-term-ru">в мечетях города</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">مَفَاتِيحُ الْفَنَادِقِ</span><span class="rule-term-ru">ключи гостиниц</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">لَا</span><span class="rule-term-ru">нет: отрицательный ответ</span></div><div class="rule-meaning-card rule-term-default"><span class="rule-term-ar" dir="rtl" lang="ar">أَ</span><span class="rule-term-ru">вопросительная хамза: частица общего вопроса</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">أَلْـ</span><span class="rule-term-ru">определённый артикль</span></div><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar" dir="rtl" lang="ar">وَ</span><span class="rule-term-ru">и / а: союз عَطْف</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Как применять</span><ol><li>Найдите два имени, связанные смыслом принадлежности.</li><li>Первое имя - مُضَافٌ: без танвина и без أَلْـ.</li><li>Второе имя - مُضَافٌ إِلَيْهِ: всегда в جَرّ.</li></ol></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры</span><div class="rule-example-list"><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">فِي الْمَسَاجِدِ</span><span class="rule-example-ru">в мечетях.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">فِي مَسَاجِدِ الْمَدِينَةِ</span><span class="rule-example-ru">в мечетях города.</span></div><div class="rule-example-card rule-term-particle"><span class="rule-example-ar" dir="rtl" lang="ar">مَفَاتِيحُ الْفَنَادِقِ</span><span class="rule-example-ru">ключи гостиниц; здесь الْفَنَادِقِ имеет артикль.</span></div></div></div><div class="rule-study-card rule-study-source"><span class="rule-card-kicker">Подробное объяснение</span><div class="rule-study-text">Диптот получает обычную касру в родительном падеже, если он определён артиклем или является первым членом идафы.<br><br><ul><li><b>فِي الْمَسَاجِدِ</b> — в мечетях.</li><li><b>فِي مَسَاجِدِ الْمَدِينَةِ</b> — в мечетях города.</li><li><b>مَفَاتِيحُ الْفَنَادِقِ</b> — ключи гостиниц; здесь <b>الْفَنَادِقِ</b> имеет артикль.</li></ul><br><br><b>Сводная таблица:</b><br><br><table><thead><tr><th>Условие</th><th>Именительный</th><th>Винительный</th><th>Родительный</th></tr></thead><tbody><tr><td>Обычное трёхпадежное слово</td><td><b>ـٌ</b></td><td><b>ـً</b></td><td><b>ـٍ</b></td></tr><tr><td>Диптот без <b>أَلْـ</b> и не в позиции первого члена идафы</td><td><b>ـُ</b></td><td><b>ـَ</b></td><td><b>ـَ</b></td></tr><tr><td>Диптот с <b>أَلْـ</b> или как первый член идафы</td><td><b>ـُ</b></td><td><b>ـَ</b></td><td><b>ـِ</b></td></tr></tbody></table><br><br></div></div><div class="rule-check-card"><b>Частая ошибка.</b> Главная ошибка: дать первому члену идафы танвин или артикль одновременно с идафой.</div></div>', 2, 'rule', 'Название и смысл عَوْدُ الْكَسْرَةِ مَعَ أَلْـ أَوِ الْإِضَافَةِ возвращение касры с артиклем или в идафе. Диптот получает обычную касру в родительном падеже, если он определён артиклем или является первым членом идафы. فِي الْمَسَاجِدِ — в');
